(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("virgil-georgics-b",[{"sp":"HDR","t":"Liber I","st":"1"},{"sp":"N","t":"Quid faciat laetas segetes, quo sidere terram<br>vertere, Maecenas, ulmisque adiungere vitis<br>conveniat, quae cura boum, qui cultus habendo<br>sit pecori, apibus quanta experientia parcis,<br>hinc canere incipiam. Vos, o clarissima mundi<br>lumina, labentem caelo quae ducitis annum,<br>Liber et alma Ceres, vestro si munere tellus<br>Chaoniam pingui glandem mutavit arista,<br>poculaque inventis Acheloia miscuit uvis;<br>et vos, agrestum praesentia numina, Fauni,<br>ferte simul Faunique pedem Dryadesque puellae:<br>Munera vestra cano. Tuque o, cui prima frementem<br>fudit equum magno tellus percussa tridenti,<br>Neptune; et cultor nemorum, cui pinguia Ceae<br>ter centum nivei tondent dumeta iuvenci;<br>ipse nemus linquens patrium saltusque Lycaei,<br>Pan, ovium custos, tua si tibi Maenala curae,<br>adsis, o Tegeaee, favens, oleaeque Minerva<br>inventrix, uncique puer monstrator aratri,<br>et teneram ab radice ferens, Silvane, cupressum,<br>dique deaeque omnes, studium quibus arva tueri,<br>quique novas alitis non ullo semine fruges,<br>quique satis largum caelo demittitis imbrem;<br>tuque adeo, quem mox quae sint habitura deorum<br>concilia, incertum est, urbisne invisere, Caesar,<br>terrarumque velis curam et te maximus orbis<br>auctorem frugum tempestatumque potentem<br>accipiat, cingens materna tempora myrto,<br>an deus inmensi venias maris ac tua nautae<br>numina sola colant, tibi serviat ultima Thule<br>teque sibi generum Tethys emat omnibus undis,<br>anne novum tardis sidus te mensibus addas,<br>qua locus Erigonen inter Chelasque sequentis<br>panditur — -ipse tibi iam bracchia contrahit ardens<br>Scorpius et caeli iusta plus parte reliquit — -<br>quidquid eris, — -nam te nec sperant Tartara regem<br>nec tibi regnandi veniat tam dira cupido,<br>quamvis Elysios miretur Graecia campos<br>nec repetita sequi curet Proserpina matrem — -<br>da facilem cursum atque audacibus adnue coeptis<br>ignarosque viae mecum miseratus agrestis<br>ingredere et votis iam nunc adsuesce vocari.","st":"1"},{"sp":"N","t":"Vere novo, gelidus canis cum montibus humor<br>liquitur et Zephyro putris se glaeba resolvit,<br>depresso incipiat iam tum mihi taurus aratro<br>ingemere et sulco attritus splendescere vomer.<br>Illa seges demum votis respondet avari<br>agricolae, bis quae solem, bis frigora sensit;<br>illius inmensae ruperunt horrea messes.<br>At prius ignotum ferro quam scindimus aequor,<br>ventos et varium caeli praediscere morem<br>cura sit ac patrios cultusque habitusque locorum<br>et quid quaeque ferat regio et quid quaeque recuset.<br>Hic segetes, illic veniunt felicius uvae,<br>arborei fetus alibi, atque iniussa virescunt<br>gramina. Nonne vides, croceos ut Tmolus odores,<br>India mittit ebur, molles sua tura Sabaei,<br>at Chalybes nudi ferrum, virosaque Pontus<br>castorea, Eliadum palmas Epiros equarum.<br>Continuo has leges aeternaque foedera certis<br>inposuit natura locis, quo tempore primum<br>Deucalion vacuum lapides iactavit in orbem,<br>unde homines nati, durum genus. Ergo age, terrae<br>pingue solum primis extemplo a mensibus anni<br>fortes invertant tauri glaebasque iacentis<br>pulverulenta coquat maturis solibus aestas;<br>at si non fuerit tellus fecunda, sub ipsum<br>Arcturum tenui sat erit suspendere sulco:<br>illic, officiant laetis ne frugibus herbae,<br>hic, sterilem exiguus ne deserat humor harenam.","st":"1"},{"sp":"N","t":"Alternis idem tonsas cessare novalis<br>et segnem patiere situ durescere campum;<br>aut ibi flava seres mutato sidere farra,<br>unde prius laetum siliqua quassante legumen<br>aut tenuis fetus viciae tristisque lupini<br>sustuleris fragilis calamos silvamque sonantem.<br>Urit enim lini campum seges, urit avenae,<br>urunt Lethaeo perfusa papavera somno:<br>sed tamen alternis facilis labor, arida tantum<br>ne saturare fimo pingui pudeat sola neve<br>effetos cinerem inmundum iactare per agros.<br>Sic quoque mutatis requiescunt fetibus arva;<br>nec nulla interea est inaratae gratia terrae.<br>Saepe etiam sterilis incendere profuit agros<br>atque levem stipulam crepitantibus urere flammis:<br>sive inde occultas viris et pabula terrae<br>pinguia concipiunt, sive illis omne per ignem<br>excoquitur vitium atque exsudat inutilis humor,<br>seu pluris calor ille vias et caeca relaxat<br>spiramenta, novas veniat qua sucus in herbas,<br>seu durat magis et venas adstringit hiantis,<br>ne tenues pluviae rapidive potentia solis<br>acrior aut Boreae penetrabile frigus adurat.<br>Multum adeo, rastris glaebas qui frangit inertis<br>vimineasque trahit cratis, iuvat arva, neque illum<br>flava Ceres alto nequiquam spectat Olympo;<br>et qui, proscisso quae suscitat aequore terga,<br>rursus in obliquum verso perrumpit aratro,<br>exercetque frequens tellurem atque imperat arvis.<br>Humida solstitia atque hiemes orate serenas,<br>agricolae; hiberno laetissima pulvere farra,<br>laetus ager: nullo tantum se Mysia cultu<br>iactat et ipsa suas mirantur Gargara messis.<br>Quid dicam, iacto qui semine comminus arva<br>insequitur cumulosque ruit male pinguis harenae<br>deinde satis fluvium inducit rivosque sequentis<br>et, cum exustus ager morientibus aestuat herbis,<br>ecce supercilio clivosi tramitis undam<br>elicit. illa cadens raucum per levia murmur<br>saxa ciet, scatebrisque arentia temperat arva.<br>Quid qui, ne gravidis procumbat culmus aristis,<br>luxuriem segetum tenera depascit in herba,<br>cum primum sulcos aequant sata. quique paludis<br>collectum humorem bibula deducit harena.<br>Praesertim incertis si mensibus amnis abundans<br>exit et obducto late tenet omnia limo,<br>unde cavae tepido sudant humore lacunae.","st":"1"},{"sp":"N","t":"Nec tamen, haec cum sint hominumque boumque labores<br>versando terram experti, nihil inprobus anser<br>Strymoniaeque grues et amaris intiba fibris<br>officiunt aut umbra nocet. Pater ipse colendi<br>haud facilem esse viam voluit, primusque per artem<br>movit agros curis acuens mortalia corda<br>nec torpere gravi passus sua regna veterno.<br>Ante Iovem nulli subigebant arva coloni;<br>ne signare quidem aut partiri limite campum<br>fas erat: in medium quaerebant ipsaque tellus<br>omnia liberius nullo poscente ferebat.<br>Ille malum virus serpentibus addidit atris<br>praedarique lupos iussit pontumque moveri,<br>mellaque decussit foliis ignemque removit<br>et passim rivis currentia vina repressit,<br>ut varias usus meditando extunderet artis<br>paulatim et sulcis frumenti quaereret herbam.<br>[Ut silicis venis abstrusum excuderet ignem.]<br>Tunc alnos primum fluvii sensere cavatas;<br>navita tum stellis numeros et nomina fecit,<br>Pleiadas, Hyadas, claramque Lycaonis Arcton;<br>tum laqueis captare feras et fallere visco<br>inventum et magnos canibus circumdare saltus;<br>atque alius latum funda iam verberat amnem<br>alta petens, pelagoque alius trahit humida lina;<br>tum ferri rigor atque argutae lamina serrae, — -<br>nam primi cuneis scindebant fissile lignum<br>tum variae venere artes. Labor omnia vicit<br>inprobus et duris urgens in rebus egestas.<br>Prima Ceres ferro mortalis vertere terram<br>instituit, cum iam glandes atque arbuta sacrae<br>deficerent silvae et victum Dodona negaret.<br>Mox et frumentis labor additus, ut mala culmos<br>esset robigo segnisque horreret in arvis<br>carduus; intereunt segetes, subit aspera silva,<br>lappaeque tribolique, interque nitentia culta<br>infelix lolium et steriles dominantur avenae.<br>Quod nisi et adsiduis herbam insectabere rastris,<br>et sonitu terrebis aves, et ruris opaci<br>falce premes umbras votisque vocaveris imbrem,<br>heu magnum alterius frustra spectabis acervum,<br>concussaque famem in silvis solabere quercu.","st":"1"},{"sp":"N","t":"Dicendum et, quae sint duris agrestibus arma,<br>quis sine nec potuere seri nec surgere messes:<br>vomis et inflexi primum grave robur aratri<br>tardaque Eleusinae matris volventia plaustra<br>tribulaque traheaeque et iniquo pondere rastri;<br>virgea praeterea Celei vilisque supellex,<br>arbuteae crates et mystica vannus Iacchi.<br>Omnia quae multo ante memor provisa repones,<br>si te digna manet divini gloria ruris.<br>Continuo in silvis magna vi flexa domatur<br>in burim et curvi formam accipit ulmus aratri.<br>Huic a stirpe pedes temo protentus in octo,<br>binae aures, duplici aptantur dentalia dorso<br>caeditur et tilia ante iugo levis altaque fagus,<br>stivaque, quae currus a tergo torqueat imos,<br>et suspensa focis explorat robora fumus.","st":"1"},{"sp":"N","t":"Possum multa tibi veterum praecepta referre,<br>ni refugis tenuisque piget cognoscere curas.<br>Area cum primis ingenti aequanda cylindro<br>et vertenda manu et creta solidanda tenaci,<br>ne subeant herbae neu pulvere victa fatiscat,<br>tum variae inludant pestes: saepe exiguus mus<br>sub terris posuitque domos atque horrea fecit,<br>aut oculis capti fodere cubilia talpae,<br>inventusque cavis bufo et quae plurima terrae<br>monstra ferunt, populatque ingentem farris acervum<br>curculio atque inopi metuens formica senectae.<br>Contemplator item, cum se nux plurima silvis<br>induet in florem et ramos curvabit olentis.<br>Si superant fetus, pariter frumenta sequentur<br>magnaque cum magno veniet tritura calore;<br>at si luxuria foliorum exuberat umbra,<br>nequiquam pinguis palea teret area culmos.<br>Semina vidi equidem multos medicare serentis<br>et nitro prius et nigra perfundere amurca,<br>grandior ut fetus siliquis fallacibus esset,<br>et, quamvis igni exiguo, properata maderent.<br>Vidi lecta diu et multo spectata labore<br>degenerare tamen, ni vis humana quot annis<br>maxima quaeque manu legeret. Sic omnia fatis<br>in peius ruere ac retro sublapsa referri,<br>non aliter, quam qui adverso vix flumine lembum<br>remigiis subigit, si bracchia forte remisit,<br>atque illum in praeceps prono rapit alveus amni.","st":"1"},{"sp":"N","t":"Praeterea tam sunt Arcturi sidera nobis<br>Haedorumque dies servandi et lucidus Anguis,<br>quam quibus in patriam ventosa per aequora vectis<br>pontus et ostriferi fauces temptantur Abydi.<br>Libra die somnique pares ubi fecerit horas<br>et medium luci atque umbris iam dividit orbem,<br>exercete, viri, tauros, serite hordea campis<br>usque sub extremum brumae intractabilis imbrem;<br>nec non et lini segetem et Cereale papaver<br>tempus humo tegere et iamdudum incumbere aratris,<br>dum sicca tellure licet, dum nubila pendent.<br>Vere fabis satio; tum te quoque, Medica, putres<br>accipiunt sulci et milio venit annua cura,<br>candidus auratis aperit cum cornibus annum<br>Taurus et averso cedens Canis occidit astro.<br>At si triticeam in messem robustaque farra<br>exercebis humum solisque instabis aristis,<br>ante tibi Eoae Atlantides abscondantur<br>Gnosiaque ardentis decedat stella Coronae,<br>debita quam sulcis committas semina quamque<br>invitae properes anni spem credere terrae.<br>Multi ante occasum Maiae coepere; sed illos<br>exspectata seges vanis elusit avenis.<br>Si vero viciamque seres vilemque phaselum<br>nec Pelusiacae curam aspernabere lentis,<br>haud obscura cadens mittet tibi signa Bootes:<br>incipe et ad medias sementem extende pruinas.","st":"1"},{"sp":"N","t":"Idcirco certis dimensum partibus orbem<br>per duodena regit mundi Sol aureus astra.<br>Quinque tenent caelum zonae; quarum una corusco<br>semper sole rubens et torrida semper ab igni;<br>quam circum extremae dextra laevaque trahuntur<br>caeruleae, glacie concretae atque imbribus atris;<br>has inter mediamque duae mortalibus aegris<br>munere concessae divom, et via secta per ambas,<br>obliquus qua se signorum verteret ordo.<br>Mundus, ut ad Scythiam Rhipaeasque arduus arces<br>consurgit, premitur Libyae devexus in austros.<br>Hic vertex nobis semper sublimis; at illum<br>sub pedibus Styx atra videt Manesque profundi.<br>Maximus hic flexu sinuoso elabitur Anguis<br>circum perque duas in morem fluminis Arctos,<br>Arctos Oceani metuentis aequore tingui.<br>Illic, ut perhibent, aut intempesta silet nox,<br>semper et obtenta densentur nocte tenebrae,<br>aut redit a nobis Aurora diemque reducit;<br>nosque ubi primus equis Oriens adflavit anhelis,<br>illic, sera rubens accendit lumina Vesper.<br>Hinc tempestates dubio praediscere caelo<br>possumus, hinc messisque diem tempusque serendi,<br>et quando infidum remis inpellere marmor<br>conveniat, quando armatas deducere classis,<br>aut tempestivam silvis evertere pinum.","st":"1"},{"sp":"N","t":"Nec frustra signorum obitus speculamur et ortus,<br>temporibusque parem diversis quattuor annum.<br>Frigidus agricolam si quando continet imber,<br>multa, forent quae mox caelo properanda sereno,<br>maturare datur: durum procudit arator<br>vomeris obtunsi dentem, cavat arbore lintres,<br>aut pecori signum aut numeros inpressit acervis.<br>Exacuunt alii vallos furcasque bicornis<br>atque Amerina parant lentae retinacula viti.<br>Nunc facilis rubea texatur fiscina virga,<br>nunc torrete igni fruges, nunc frangite saxo.<br>Quippe etiam festis quaedam exercere diebus<br>fas et iura sinunt; rivos deducere nulla<br>religio vetuit, segeti praetendere saepem,<br>insidias avibus moliri, incendere vepres,<br>balantumque gregem fluvio mersare salubri.<br>Saepe oleo tardi costas agitator aselli<br>vilibus aut onerat pomis, lapidemque revertens<br>incusum aut atrae massam picis urbe reportat.","st":"1"},{"sp":"N","t":"Ipsa dies alios alio dedit ordine Luna<br>felicis operum. Quintam fuge: pallidus Orcus<br>Eumenidesque satae; tum partu Terra nefando<br>Coeumque Iapetumque creat saevumque Typhoea<br>et coniuratos caelum rescindere fratres.<br>Ter sunt conati inponere Pelio Ossam<br>scilicet, atque Ossae frondosum involvere Olympum;<br>ter pater exstructos disiecit fulmine montis.<br>Septima post decimam felix et ponere vitem<br>et prensos domitare boves et licia telae<br>addere: nona fugae melior, contraria furtis.","st":"1"},{"sp":"N","t":"Multa adeo gelida melius se nocte dedere,<br>aut cum sole novo terras inrorat Eous.<br>Nocte leves melius stipulae, nocte arida prata<br>tondentur, noctes lentus non deficit humor.<br>Et quidam seros hiberni ad luminis ignis<br>pervigilat ferroque faces inspicat acuto;<br>interea longum cantu solata laborem<br>arguto coniunx percurrit pectine telas,<br>aut dulcis musti Volcano decoquit humorem<br>et foliis undam trepidi despumat aeni.<br>At rubicunda Ceres medio succiditur aestu<br>et medio tostas aestu terit area fruges.<br>Nudus ara, sere nudus; hiems ignava colono.<br>Frigoribus parto agricolae plerumque fruuntur<br>mutuaque inter se laeti convivia curant.<br>Invitat genialis hiems curasque resolvit,<br>ceu pressae cum iam portum tetigere carinae,<br>puppibus et laeti nautae inposuere coronas.<br>Sed tamen et quernas glandes tum stringere tempus<br>et lauri bacas oleamque cruentaque myrta,<br>tum gruibus pedicas et retia ponere cervis<br>auritosque sequi lepores, tum figere dammas,<br>stuppea torquentem Balearis verbera fundae,<br>cum nix alta iacet, glaciem cum flumina trudunt.","st":"1"},{"sp":"N","t":"Quid tempestates autumni et sidera dicam,<br>atque, ubi iam breviorque dies et mollior aestas,<br>quae vigilanda viris. vel cum ruit imbriferum ver,<br>spicea iam campis cum messis inhorruit et cum<br>frumenta in viridi stipula lactentia turgent.<br>Saepe ego, cum flavis messorem induceret arvis<br>agricola et fragili iam stringeret hordea culmo,<br>omnia ventorum concurrere proelia vidi,<br>quae gravidam late segetem ab radicibus imis<br>sublimem expulsam eruerent; ita turbine nigro<br>ferret hiems culmumque levem stipulasque volantis.<br>Saepe etiam inmensum caelo venit agmen aquarum<br>et foedam glomerant tempestatem imbribus atris<br>collectae ex alto nubes; ruit arduus aether<br>et pluvia ingenti sata laeta boumque labores<br>diluit; inplentur fossae et cava flumina crescunt<br>cum sonitu fervetque fretis spirantibus aequor.<br>Ipse pater media nimborum in nocte corusca<br>fulmina molitur dextra; quo maxuma motu<br>terra tremit; fugere ferae et mortalia corda<br>per gentis humilis stravit pavor; ille flagranti<br>aut Athon aut Rhodopen aut alta Ceraunia telo<br>deicit; ingeminant austri et densissimus imber;<br>nunc nemora ingenti vento, nunc litora plangunt.<br>Hoc metuens caeli menses et sidera serva,<br>frigida Saturni sese quo stella receptet,<br>quos ignis caelo Cyllenius erret in orbis.<br>In primis venerare deos atque annua magnae<br>sacra refer Cereri laetis operatus in herbis<br>extremae sub casum hiemis, iam vere sereno.<br>Tum pingues agni et tum mollissima vina,<br>tum somni dulces densaeque in montibus umbrae.<br>Cuncta tibi Cererem pubes agrestis adoret;<br>cui tu lacte favos et miti dilue Baccho,<br>terque novas circum felix eat hostia fruges,<br>omnis quam chorus et socii comitentur ovantes,<br>et Cererem clamore vocent in tecta; neque ante<br>falcem maturis quisquam supponat aristis,<br>quam Cereri torta redimitus tempora quercu<br>det motus incompositos et carmina dicat.","st":"1"},{"sp":"N","t":"Atque haec ut certis possemus discere signis,<br>aestusque pluviasque et agentis frigora ventos,<br>ipse Pater statuit, quid menstrua Luna moneret,<br>quo signo caderent austri, quid saepe videntes<br>agricolae propius stabulis armenta tenerent.<br>Continuo ventis surgentibus aut freta ponti<br>incipiunt agitata tumescere et aridus altis<br>montibus audiri fragor aut resonantia longe<br>litora misceri et nemorum increbrescere murmur.<br>Iam sibi tum a curvis male temperat unda carinis,<br>cum medio celeres revolant ex aequore mergi<br>clamoremque ferunt ad litora, cumque marinae<br>in sicco ludunt fulicae notasque paludes<br>deserit atque altam supra volat ardea nubem.<br>Saepe etiam stellas vento inpendente videbis<br>praecipitis caelo labi noctisque per umbram<br>flammarum longos a tergo albescere tractus;<br>saepe levem paleam et frondes volitare caducas<br>aut summa nantis in aqua colludere plumas.<br>At Boreae de parte trucis cum fulminat et cum<br>Eurique Zephyrique tonat domus: omnia plenis<br>rura natant fossis atque omnis navita ponto<br>humida vela legit. Numquam inprudentibus imber<br>obfuit: aut illum surgentem vallibus imis<br>aeriae fugere grues, aut bucula caelum<br>suspiciens patulis captavit naribus auras,<br>aut arguta lacus circumvolitavit hirundo<br>et veterem in limo ranae cecinere querelam.<br>Saepius et tectis penetralibus extulit ova<br>angustum formica terens iter et bibit ingens<br>arcus et e pastu decedens agmine magno<br>corvorum increpuit densis exercitus alis.<br>Iam variae pelagi volucres et quae Asia circum<br>dulcibus in stagnis rimantur prata Caystri,<br>certatim largos umeris infundere rores:<br>nunc caput obiectare fretis, nunc currere in undas<br>et studio incassum videas gestire lavandi.<br>Tum cornix plena pluviam vocat inproba voce<br>et sola in sicca secum spatiatur harena.<br>Ne nocturna quidem carpentes pensa puellae<br>nescivere hiemem, testa cum ardente viderent<br>scintillare oleum et putris concrescere fungos.","st":"1"},{"sp":"N","t":"Nec minus ex imbri soles et aperta serena<br>prospicere et certis poteris cognoscere signis:<br>nam neque tum stellis acies obtunsa videtur,<br>nec fratris radiis obnoxia surgere Luna,<br>tenuia nec lanae per caelum vellera ferri;<br>non tepidum ad solem pinnas in litore pandunt<br>dilectae Thetidi alcyones, non ore solutos<br>inmundi meminere sues iactare maniplos.<br>At nebulae magis ima petunt campoque recumbunt,<br>solis et occasum servans de culmine summo<br>nequiquam seros exercet noctua cantus.<br>Adparet liquido sublimis in aere Nisus<br>et pro purpureo poenas dat Scylla capillo:<br>quacumque illa levem fugiens secat aethera pinnis,<br>ecce inimicus, atrox, magno stridore per auras<br>insequitur Nisus; qua se fert Nisus ad auras,<br>illa levem fugiens raptim secat aethera pinnis<br>Tum liquidas corvi presso ter gutture voces<br>aut quater ingeminant, et saepe cubilibus altis<br>nescio qua praeter solitum dulcedine laeti<br>inter se in foliis strepitant; iuvat imbribus actis<br>progeniem parvam dulcisque revisere nidos;<br>haud equidem credo, quia sit divinitus illis<br>ingenium aut rerum fato prudentia maior;<br>verum ubi tempestas et caeli mobilis humor<br>mutavere vias et Iuppiter uvidus austris<br>denset, erant quae rara modo, et, quae densa, relaxat,<br>vertuntur species animorum et pectora motus<br>nunc alios, alios, dum nubila ventus agebat,<br>concipiunt: hinc ille avium concentus in agris<br>et laetae pecudes et ovantes gutture corvi.","st":"1"},{"sp":"N","t":"Si vero solem ad rapidum lunasque sequentis<br>ordine respicies, numquam te crastina fallet<br>hora neque insidiis noctis capiere serenae.<br>Luna, revertentis cum primum colligit ignis,<br>si nigrum obscuro conprenderit aera cornu,<br>maxumus agricolis pelagoque parabitur imber;<br>at si virgineum suffuderit ore ruborem,<br>ventus erit; vento semper rubet aurea Phoebe.<br>Sin ortu quarto, namque is certissimus auctor,<br>pura neque obtunsis per caelum cornibus ibit,<br>totus et ille dies et qui nascentur ab illo<br>exactum ad mensem pluvia ventisque carebunt,<br>votaque servati solvent in litore nautae<br>Glauco et Panopeae et Inoo Melicertae.<br>Sol quoque et exoriens et cum se condet in undas<br>signa dabit; solem certissima signa sequuntur,<br>et quae mane refert et quae surgentibus astris.<br>Ille ubi nascentem maculis variaverit ortum<br>conditus in nubem medioque refugerit orbe,<br>suspecti tibi sint imbres; namque urget ab alto<br>arboribusque satisque Notus pecorique sinister.<br>Aut ubi sub lucem densa inter nubila sese<br>diversi rumpent radii aut ubi pallida surget<br>Tithoni croceum linquens Aurora cubile,<br>heu male tum mitis defendet pampinus uvas:<br>tam multa in tectis crepitans salit horrida grando.<br>Hoc etiam, emenso cum iam decedit Olympo,<br>profuerit meminisse magis; nam saepe videmus<br>ipsius in voltu varios errare colores:<br>caeruleus pluviam denuntiat, igneus Euros;<br>sin maculae incipient rutilo inmiscerier igni,<br>omnia tum pariter vento nimbisque videbis<br>fervere. Non illa quisquam me nocte per altum<br>ire, neque a terra moneat convellere funem.<br>At si, cum referetque diem condetque relatum,<br>lucidus orbis erit, frustra terrebere nimbis<br>et claro silvas cernes Aquilone moveri.<br>Denique quid vesper serus vehat, unde serenas<br>ventus agat nubes, quid cogitet humidus Auster,<br>sol tibi signa dabit. Solem quis dicere falsum<br>audeat. Ille etiam caecos instare tumultus<br>saepe monet fraudemque et operta tumescere bella.<br>Ille etiam exstincto miseratus Caesare Romam,<br>cum caput obscura nitidum ferrugine texit<br>inpiaque aeternam timuerunt saecula noctem.<br>Tempore quamquam illo tellus quoque et aequora ponti<br>obscenaeque canes inportunaeque volucres<br>signa dabant. Quotiens Cyclopum effervere in agros<br>vidimus undantem ruptis fornacibus Aetnam<br>flammarumque globos liquefactaque volvere saxa!<br>Armorum sonitum toto Germania caelo<br>audiit, insolitis tremuerunt motibus Alpes.<br>Vox quoque per lucos volgo exaudita silentis<br>ingens et simulacra modis pallentia miris<br>visa sub obscurum noctis, pecudesque locutae,<br>infandum! sistunt amnes terraeque dehiscunt<br>et maestum inlacrimat templis ebur aeraque sudant.<br>Proluit insano contorquens vertice silvas<br>fluviorum rex Eridanus camposque per omnis<br>cum stabulis armenta tulit. Nec tempore eodem<br>tristibus aut extis fibrae adparere minaces<br>aut puteis manare cruor cessavit et altae<br>per noctem resonare lupis ululantibus urbes.<br>Non alias caelo ceciderunt plura sereno<br>fulgura nec diri totiens arsere cometae.<br>ergo inter sese paribus concurrere telis<br>Romanas acies iterum videre Philippi;<br>nec fuit indignum superis, bis sanguine nostro<br>Emathiam et latos Haemi pinguescere campos.<br>Scilicet et tempus veniet, cum finibus illis<br>agricola incurvo terram molitus aratro<br>exesa inveniet scabra robigine pila<br>aut gravibus rastris galeas pulsabit inanis<br>grandiaque effossis mirabitur ossa sepulchris.<br>Di patrii, Indigetes, et romule Vestaque mater,<br>quae Tuscum Tiberim et Romana Palatia servas,<br>hunc saltem everso iuvenem succurrere saeclo<br>ne prohibete! Satis iam pridem sanguine nostro<br>Laomedonteae luimus periuria Troiae;<br>iam pridem nobis caeli te regia, Caesar,<br>invidet atque hominum queritur curare triumphos;<br>quippe ubi fas versum atque nefas: tot bella per orbem,<br>tam multae scelerum facies; non ullus aratro<br>dignus honos, squalent abductis arva colonis<br>et curvae rigidum falces conflantur in ensem.<br>Hinc movet Euphrates, illinc Germania bellum;<br>vicinae ruptis inter se legibus urbes<br>arma ferunt; saevit toto Mars inpius orbe;<br>ut cum carceribus sese effudere quadrigae,<br>addunt in spatia et frustra retinacula tendens<br>fertur equis auriga neque audit currus habenas.","st":"1"},{"sp":"HDR","t":"Liber II","st":"2"},{"sp":"N","t":"Hactenus arvorum cultus et sidera caeli,<br>nunc te, Bacche, canam, nec non silvestria tecum<br>virgulta et prolem tarde crescentis olivae.<br>Huc, pater o Lenaee — -tuis hic omnia plena<br>muneribus, tibi pampineo gravidus autumno<br>floret ager, spumat plenis vindemia labris — -<br>huc, pater o Lenaee, veni nudataque musto<br>tingue novo mecum direptis crura cothurnis.","st":"2"},{"sp":"N","t":"Principio arboribus varia est natura creandis.<br>namque aliae nullis hominum cogentibus ipsae<br>sponte sua veniunt camposque et flumina late<br>curva tenent, ut molle siler lentaeque genestae,<br>populus et glauca canentia fronde salicta;<br>pars autem posito surgunt de semine, ut altae<br>castaneae nemorumque Iovi quae maxima frondet<br>aesculus atque habitae Grais oracula quercus.<br>Pullulat ab radice aliis densissima silva,<br>ut cerasis ulmisque; etiam Parnasia laurus<br>parva sub ingenti matris se subicit umbra.<br>Hos natura modos primum dedit, his genus omne<br>silvarum fruticumque viret nemorumque sacrorum.","st":"2"},{"sp":"N","t":"Sunt aliae, quas ipse via sibi repperit usus.<br>Hic plantas tenero abscindens de corpore matrum<br>deposuit sulcis, hic stirpes obruit arvo<br>quadrifidasque sudes et acuto robore vallos;<br>silvarumque aliae pressos propaginis arcus<br>exspectant et viva sua plantaria terra;<br>nil radicis egent aliae summumque putator<br>haud dubitat terrae referens mandare cacumen.<br>Quin et caudicibus sectis — -mirabile dictu — -<br>truditur e sicco radix oleagina ligno.<br>Et saepe alterius ramos inpune videmus<br>vertere in alterius mutatamque insita mala<br>ferre pirum et prunis lapidosa rubescere corna.","st":"2"},{"sp":"N","t":"Quare agite o proprios generatim discite cultus,<br>agricolae, fructusque feros mollite colendo,<br>neu segnes iaceant terrae. Iuvat Ismara Baccho<br>conserere atque olea magnum vestire Taburnum.<br>Tuque ades inceptumque una decurre laborem,<br>O decus, o famae merito pars maxima nostrae,<br>Maecenas, pelagoque volans da vela patenti;<br>non ego cuncta meis amplecti versibus opto,<br>non, mihi si linguae centum sint oraque centum,<br>ferrea vox; ades et primi lege litoris oram.<br>In manibus terrae; non hic te carmine ficto<br>atque per ambages et longa exorsa tenebo.","st":"2"},{"sp":"N","t":"Sponte sua quae se tollunt in luminis oras,<br>infecunda quidem, sed laeta et fortia surgunt;<br>quippe solo natura subest. Tamen haec quoque, si quis<br>inserat aut scrobibus mandet mutata subactis,<br>exuerint silvestrem animum cultuque frequenti<br>in quascumque voles artis haud tarda sequentur.<br>Nec non et sterilis, quae stirpibus exit ab imis,<br>hoc faciat, vacuos si sit digesta per agros;<br>nunc altae frondes et rami matris opacant<br>crescentique adimunt fetus uruntque ferentem.<br>Iam quae seminibus iactis se sustulit arbos<br>tarda venit seris factura nepotibus umbram,<br>pomaque degenerant sucos oblita priores<br>et turpis avibus praedam fert uva racemos.<br>Scilicet omnibus est labor inpendendus et omnes<br>cogendae in sulcum ac multa mercede domandae.<br>Sed truncis oleae melius, propagine vites<br>respondent, solido Paphiae de robore myrtus;<br>plantis et durae coryli nascuntur et ingens<br>fraxinus Herculeaeque arbos umbrosa coronae<br>Chaoniique patris glandes, etiam ardua palma<br>nascitur et casus abies visura marinos.","st":"2"},{"sp":"N","t":"Inseritur vero et fetu nucis arbutus horrida,<br>et steriles platani malos gessere valentis;<br>castaneae fagus, ornusque incanuit albo<br>flore piri glandemque sues fregere sub ulmis.<br>Nec modus inserere atque oculos inponere simplex.<br>Nam qua se medio trudunt de cortice gemmae<br>et tenuis rumpunt tunicas, angustus in ipso<br>fit nodo sinus: huc aliena ex arbore germen<br>includunt udoque docent inolescere libro.<br>Aut rursum enodes trunci resecantur et alte<br>finditur in solidum cuneis via, deinde feraces<br>plantae inmittuntur: nec longum tempus, et ingens<br>exsilit ad caelum ramis felicibus arbos<br>miraturque novas frondes et non sua poma.","st":"2"},{"sp":"N","t":"Praeterea genus haud unum nec fortibus ulmis<br>nec salici lotoque neque Idaeis cyparissis,<br>nec pingues unam in faciem nascuntur olivae,<br>orchades et radii et amara pausia baca<br>pomaque et Alcinoi silvae, nec surculus idem<br>Crustumiis Syriisque piris gravibusque volemis.<br>Non eadem arboribus pendet vindemia nostris,<br>quam Methymnaeo carpit de palmite Lesbos;<br>sunt Thasiae vites, sunt et Mareotides albae,<br>pinguibus hae terris habiles, levioribus illae,<br>et passo Psithia utilior tenuisque Lageos<br>temptatura pedes olim vincturaque linguam,<br>purpureae preciaeque, et quo te carmine dicam,<br>Rhaetica? Nec cellis ideo contende Falernis.<br>Sunt et Amineae vites, firmissima vina,<br>Tmolius adsurgit quibus et rex ipse Phanaeus;<br>Argitisque minor, cui non certaverit ulla<br>aut tantum fluere aut totidem durare per annos.<br>Non ego te, Dis et mensis accepta secundis,<br>transierim, Rhodia, et tumidis, Bumaste, racemis.<br>Sed neque quam multae species nec nomina quae sint,<br>est numerus; neque enim numero conprendere refert;<br>quem qui scire velit, Libyci velit aequoris idem<br>discere quam multae Zephyro turbentur harenae,<br>aut ubi navigiis violentior incidit Eurus,<br>nosse, quot Ionii veniant ad litora fluctus.","st":"2"},{"sp":"N","t":"Nec vero terrae ferre omnes omnia possunt.<br>fluminibus salices crassisque paludibus alni<br>nascuntur, steriles saxosis montibus orni;<br>litora myrtetis laetissima; denique apertos<br>Bacchus amat collis, aquilonem et frigora taxi.<br>Aspice et extremis domitum cultoribus orbem<br>Eoasque domos Arabum pictosque Gelonos:<br>divisae arboribus patriae. Sola India nigrum<br>fert ebenum, solis est turea virga Sabaeis.<br>Quid tibi odorato referam sudantia ligno<br>balsamaque et bacas semper frondentis acanthi?<br>Quid nemora Aethiopum molli canentia lana,<br>velleraque ut foliis depectant tenuia Seres;<br>aut quos Oceano propior gerit India lucos,<br>extremi sinus orbis, ubi aera vincere summum<br>arboris haud ullae iactu potuere sagittae?<br>Et gens illa quidem sumptis non tarda pharetris.<br>Media fert tristis sucos tardumque saporem<br>felicis mali, quo non praesentius ullum,<br>pocula si quando saevae infecere novercae,<br>miscueruntque herbas et non innoxia verba,<br>auxilium venit ac membris agit atra venena.<br>Ipsa ingens arbos faciemque simillima lauro;<br>et, si non alium late iactaret odorem,<br>laurus erat; folia haud ullis labentia ventis;<br>flos ad prima tenax; animas et olentia Medi<br>ora fovent illo et senibus medicantur anhelis.<br>sed neque Medorum, silvae ditissima, terra,<br>nec pulcher Ganges atque auro turbidus Hermus<br>laudibus Italiae certent, non Bactra neque Indi<br>totaque turiferis Panchaia pinguis harenis.<br>Haec loca non tauri spirantes naribus ignem<br>invertere satis inmanis dentibus hydri<br>nec galeis densisque virum seges horruit hastis;<br>sed gravidae fruges et Bacchi Massicus humor<br>inplevere; tenent oleae armentaque laeta.<br>Hinc bellator equus campo sese arduus infert;<br>hinc albi, Clitumne, greges et maxima taurus<br>victima, saepe tuo perfusi flumine sacro,<br>Romanos ad templa deum duxere triumphos.<br>Hic ver adsiduum atque alienis mensibus aestas<br>bis gravidae pecudes, bis pomis utilis arbos.<br>At rabidae tigres absunt et saeva leonum<br>semina nec miseros fallunt aconita legentis<br>nec rapit inmensos orbis per humum neque tanto<br>squameus in spiram tractu se colligit anguis.<br>Adde tot egregias urbes operumque laborem,<br>tot congesta manu praeruptis oppida saxis<br>fluminaque antiquos subter labentia muros.<br>An mare, quod supra, memorem, quodque adluit infra<br>anne lacus tantos? Te, Lari maxume, teque,<br>fluctibus et fremitu adsurgens Benace marino<br>an memorem portus Lucrinoque addita claustra<br>atque indignatum magnis stridoribus aequor<br>Iulia qua ponto longe sonat unda refuso<br>Tyrrhenusque fretis inmittitur aestus Avernis?<br>Haec eadem argenti rivos aerisque metalla<br>ostendit venis atque auro plurima fluxit.<br>Haec genus acre virum, Marsos pubemque Sabellam<br>adsuetumque malo Ligurem Volscosque verutos<br>extulit, haec Decios, Marios, magnosque Camillos,<br>Scipiadas duros bello et te, maxume Caesar,<br>qui nunc extremis Asiae iam victor in oris<br>inbellem avertis Romanis arcibus Indum.<br>Salve, magna parens frugum, Saturnia tellus,<br>magna virum; tibi res antiquae laudis et artem<br>ingredior, sanctos ausus recludere fontis,<br>Ascraeumque cano Romana per oppida carmen.","st":"2"},{"sp":"N","t":"Nunc locus arvorum ingeniis: quae robora cuique,<br>quis color et quae sit rebus natura ferendis.<br>Difficiles primum terrae collesque maligni,<br>tenuis ubi argilla et dumosis calculus arvis,<br>Palladia gaudent silva vivacis olivae.<br>Indicio est tractu surgens oleaster eodem<br>plurimus et strati bacis silvestribus agri.<br>At quae pinguis humus dulcique uligine laeta,<br>quique frequens herbis et fertilis ubere campus — -<br>qualem saepe cava montis convalle solemus<br>despicere; huc summis liquuntur rupibus amnes<br>felicemque trahunt limum — -quique editus austro<br>et filicem curvis invisam pascit aratris:<br>hic tibi praevalidas olim multoque fluentis<br>sufficiet Baccho vitis, hic fertilis uvae,<br>hic laticis, qualem pateris libamus et auro,<br>inflavit cum pinguis ebur Tyrrhenus ad aras,<br>lancibus et pandis fumantia reddimus exta.<br>Sin armenta magis studium vitulosque tueri<br>aut ovium fetum aut urentis culta capellas,<br>saltus et saturi petito longinqua Tarenti<br>et qualem infelix amisit Mantua campum,<br>pascentem niveos herboso flumine cycnos;<br>non liquidi gregibus fontes, non gramina deerunt;<br>et, quantum longis carpent armenta diebus,<br>exigua tantum gelidus ros nocte reponet.<br>Nigra fere et presso pinguis sub vomere terra<br>et cui putre solum, — -namque hoc imitamur arando — -<br>optima frumentis; non ullo ex aequore cernes<br>plura domum tardis decedere plaustra iuvencis;<br>aut unde iratus silvam devexit arator<br>et nemora evertit multos ignava per annos<br>antiquasque domos avium cum stirpibus imis<br>eruit; illae altum nidis petiere relictis,<br>at rudis enituit inpulso vomere campus.<br>Nam ieiuna quidem clivosi glarea ruris<br>vix humilis apibus casias roremque ministrat;<br>et tophus scaber et nigris exesa chelydris<br>creta negant alios aeque serpentibus agros<br>dulcem ferre cibum et curvas praebere latebras.<br>Quae tenuem exhalat nebulam fumosque volucris<br>et bibit humorem et, cum volt, ex se ipsa remittit<br>quaeque suo semper viridi se gramine vestit<br>nec scabie et salsa laedit robigine ferrum:<br>illa tibi laetis intexet vitibus ulmos,<br>illa ferax oleo est, illam experiere colendo<br>et facilem pecori et patientem vomeris unci.<br>Talem dives arat Capua et vicina Vesevo<br>ora iugo et vacuis Clanius non aequus Acerris.","st":"2"},{"sp":"N","t":"Nunc, quo quamque modo possis cognoscere, dicam.<br>Rara sit an supra morem si densa requires — -<br>altera frumentis quoniam favet, altera Baccho,<br>densa magis Cereri, rarissima quaeque Lyaeo — -<br>ante locum capies oculis alteque iubebis<br>in solido puteum demitti omnemque repones<br>rursus humum et pedibus summas aequabis harenas.<br>Si deerunt, rarum pecorique et vitibus almis<br>aptius uber erit; sin in sua posse negabunt<br>ire loca et scrobibus superabit terra repletis,<br>spissus ager; glaebas cunctantis crassaque terga<br>exspecta et validis terram proscinde iuvencis.<br>Salsa autem tellus et quae perhibetur amara,<br>frugibus infelix — -ea nec mansuescit arando<br>nec Baccho genus aut pomis sua nomina servat — -<br>tale dabit specimen: tu spisso vimine qualos<br>colaque prelorum fumosis deripe tectis;<br>huc ager ille malus dulcesque a fontibus undae<br>ad plenum calcentur; aqua eluctabitur omnis<br>scilicet, et grandes ibunt per vimina guttae;<br>at sapor indicium faciet manifestus et ora<br>tristia temptantum sensu torquebit amaro.<br>Pinguis item quae sit tellus, hoc denique pacto<br>discimus: haud umquam manibus iactata fatiscit,<br>sed picis in morem ad digitos lentescit habendo.<br>Humida maiores herbas alit, ipsaque iusto<br>laetior. Ah nimium ne sit mihi fertilis illa<br>nec se praevalidam primis ostendat aristis!<br>Quae gravis est, ipso tacitam se pondere prodit,<br>quaeque levis. Promptum est oculis praediscere nigram,<br>et quis cui color. At sceleratum exquirere frigus<br>difficile est: piceae tantum taxique nocentes<br>interdum aut hederae pandunt vestigia nigrae<br>his animadversis terram multo ante memento<br>excoquere et magnos scrobibus concidere montis,<br>ante supinatas aquiloni ostendere glaebas,<br>quam laetum infodias vitis genus. Optima putri<br>arva solo: id venti curant gelidaeque pruinae<br>et labefacta movens robustus iugera fossor.<br>Ac si quos haud ulla viros vigilantia fugit,<br>ante locum similem exquirunt, ubi prima paretur<br>arboribus seges et quo mox digesta feratur,<br>mutatam ignorent subito ne semina matrem.<br>Quin etiam caeli regionem in cortice signant,<br>ut, quo quaeque modo steterit, qua parte calores<br>Austrinos tulerit, quae terga obverterit axi,<br>restituant: adeo in teneris consuescere multum est.<br>Collibus an plano melius sit ponere vitem,<br>quaere prius. Si pinguis agros metabere campi,<br>densa sere; in denso non segnior ubere Bacchus;<br>sin tumulis adclive solum collisque supinos,<br>indulge ordinibus, nec setius omnis in unguem<br>arboribus positis secto via limite quadret.<br>Ut saepe ingenti bello cum longa cohortis<br>explicuit legio et campo stetit agmen aperto,<br>directaeque acies, ac late fluctuat omnis<br>aere renidenti tellus, necdum horrida miscent<br>proelia, sed dubius mediis Mars errat in armis:<br>omnia sint paribus numeris dimensa viarum;<br>non animum modo uti pascat prospectus inanem,<br>sed quia non aliter viris dabit omnibus aequas<br>terra neque in vacuum poterunt se extendere rami.","st":"2"},{"sp":"N","t":"Forsitan et scrobibus quae sint fastigia quaeras.<br>ausim vel tenui vitem committere sulco.<br>Altior ac penitus terrae defigitur arbos,<br>aesculus in primis, quae quantum vertice ad auras<br>aetherias, tantum radice in Tartara tendit.<br>Ergo non hiemes illam, non flabra neque imbres<br>convellunt; inmota manet, multosque nepotes,<br>multa virum volvens durando saecula vincit.<br>Tum fortis late ramos et bracchia pandens<br>huc illuc, media ipsa ingentem sustinet umbram.","st":"2"},{"sp":"N","t":"Neve tibi ad solem vergant vineta cadentem,<br>Neve inter vitis corylum sere, neve flagella<br>summa pete aut summa defringe ex arbore plantas<br>tantus amor terrae — -neu ferro laede retunso<br>semina, neve oleae silvestris insere truncos:<br>nam saepe incautis pastoribus excidit ignis,<br>qui furtim pingui primum sub cortice tectus<br>robora conprendit frondesque elapsus in altas<br>ingentem caelo sonitum dedit; inde secutus<br>per ramos victor perque alta cacumina regnat<br>et totum involvit flammis nemus et ruit atram<br>ad caelum picea crassus caligine nubem,<br>praesertim si tempestas a vertice silvis<br>incubuit glomeratque ferens incendia ventus.<br>Hoc ubi, non a stirpe valent caesaeque reverti<br>possunt atque ima similes revirescere terra;<br>infelix superat foliis oleaster amaris.","st":"2"},{"sp":"N","t":"Nec tibi tam prudens quisquam persuadeat auctor<br>tellurem Borea rigidam spirante movere.<br>Rura gelu tum claudit hiems nec semine iacto<br>concretam patitur radicem adfigere terrae.<br>Optima vinetis satio, cum vere rubenti<br>candida venit avis longis invisa colubris,<br>prima vel autumni sub frigora, cum rapidus Sol<br>nondum hiemem contingit equis, iam praeterit aestas.<br>Ver adeo frondi nemorum, ver utile silvis;<br>vere tument terrae et genitalia semina poscunt.<br>Tum pater omnipotens fecundis imbribus Aether<br>coniugis in gremium laetae descendit et omnis<br>magnus alit magno commixtus corpore fetus.<br>Avia tum resonant avibus virgulta canoris<br>et Venerem certis repetunt armenta diebus;<br>parturit almus ager Zephyrique tepentibus auris<br>laxant arva sinus; superat tener omnibus humor;<br>inque novos soles audent se germina tuto<br>credere, nec metuit surgentis pampinus austros<br>aut actum caelo magnis aquilonibus imbrem,<br>sed trudit gemmas et frondes explicat omnis.<br>Non alios prima crescentis origine mundi<br>inluxisse dies aliumve habuisse tenorem<br>crediderim: ver illud erat, ver magnus agebat<br>orbis et hibernis parcebant flatibus Euri,<br>cum primae lucem pecudes hausere virumque<br>terrea progenies duris caput extulit arvis,<br>inmissaeque ferae silvis et sidera caelo.<br>Nec res hunc tenerae possent perferre laborem,<br>si non tanta quies iret frigusque caloremque<br>inter, et exciperet caeli indulgentia terras.","st":"2"},{"sp":"N","t":"Quod superest, quaecumque premes virgulta per agros,<br>sparge fimo pingui et multa memor occule terra,<br>aut lapidem bibulum aut squalentis infode conchas;<br>inter enim labentur aquae tenuisque subibit<br>halitus atque animos tollent sata; iamque reperti,<br>qui saxo super atque ingentis pondere testae<br>urgerent; hoc effusos munimen ad imbris,<br>hoc, ubi hiulca siti findit canis aestifer arva.","st":"2"},{"sp":"N","t":"Seminibus positis superest diducere terram<br>saepius ad capita et duros iactare bidentis,<br>aut presso exercere solum sub vomere et ipsa<br>flectere luctantis inter vineta iuvencos;<br>tum levis calamos et rasae hastilia virgae<br>fraxineasque aptare sudes furcasque valentis,<br>viribus eniti quarum et contemnere ventos<br>adsuescant summasque sequi tabulata per ulmos.","st":"2"},{"sp":"N","t":"Ac dum prima novis adolescit frondibus aetas,<br>parcendum teneris, et dum se laetus ad auras<br>palmes agit laxis per purum inmissus habenis,<br>ipsa acie nondum falcis temptanda, sed uncis<br>carpendae manibus frondes interque legendae.<br>Inde ubi iam validis amplexae stirpibus ulmos<br>exierint, tum stringe comas, tum bracchia tonde — -<br>ante reformidant ferrum — -tum denique dura<br>exerce imperia et ramos conpesce fluentis.","st":"2"},{"sp":"N","t":"Texendae saepes etiam et pecus omne tenendum,<br>praecipue dum frons tenera inprudensque laborum;<br>cui super indignas hiemes solemque potentem<br>silvestres uri adsidue capreaeque sequaces<br>inludunt, pascuntur oves avidaeque iuvencae.<br>Frigora nec tantum cana concreta pruina<br>aut gravis incumbens scopulis arentibus aestas,<br>quantum illi nocuere greges durique venenum<br>dentis et admorso signata in stirpe cicatrix.<br>Non aliam ob culpam Baccho caper omnibus aris<br>caeditur et veteres ineunt proscaenia ludi<br>praemiaque ingeniis pagos et compita circum<br>thesidae posuere atque inter pocula laeti<br>mollibus in pratis unctos saluere per utres.<br>Nec non Ausonii, Troia gens missa, coloni<br>versibus incomptis ludunt risuque soluto<br>oraque corticibus sumunt horrenda cavatis<br>et te, Bacche, vocant per carmina laeta tibique<br>oscilla ex alta suspendunt mollia pinu.<br>Hinc omnis largo pubescit vinea fetu,<br>conplentur vallesque cavae saltusque profundi,<br>et quocumque deus circum caput egit honestum.<br>Ergo rite suum Baccho dicemus honorem<br>carminibus patriis lancesque et liba feremus<br>et ductus cornu stabit sacer hircus ad aram<br>pinguiaque in veribus torrebimus exta colurnis.","st":"2"},{"sp":"N","t":"Est etiam ille labor curandis vitibus alter,<br>cui numquam exhausti satis est: namque omne quot annis<br>terque quaterque solum scindendum glebaque versis<br>aeternum frangenda bidentibus, omne levandum<br>fronde nemus. Redit agricolis labor actus in orbem<br>atque in se sua per vestigia volvitur annus.<br>Ac iam olim, seras posuit cum vinea frondes,<br>frigidus et silvis aquilo decussit honorem,<br>iam tum acer curas venientem extendit in annum<br>rusticus et curvo Saturni dente relictam<br>persequitur vitem attondens fingitque putando.<br>Primus humum fodito, primus devecta cremato<br>sarmenta et vallos primus sub tecta referto;<br>postremus metito. Bis vitibus ingruit umbra,<br>bis segetem densis obducunt sentibus herbae;<br>durus uterque labor: laudato ingentia rura,<br>exiguum colito. Nec non etiam aspera rusci<br>vimina per silvam et ripis fluvialis arundo<br>caeditur, incultique exercet cura salicti.<br>Iam vinctae vites, iam falcem arbusta reponunt,<br>iam canit effectos extremus vinitor antes:<br>sollicitanda tamen tellus pulvisque movendus<br>et iam maturis metuendus Iuppiter uvis.","st":"2"},{"sp":"N","t":"Contra non ulla est oleis cultura; neque illae<br>procurvam exspectant falcem rastrosque tenacis,<br>cum semel haeserunt arvis aurasque tulerunt;<br>ipsa satis tellus, cum dente recluditur unco,<br>sufficit humorem et gravidas, cum vomere, fruges.<br>Hoc pinguem et placitam Paci nutritor olivam.","st":"2"},{"sp":"N","t":"Poma quoque, ut primum truncos sensere valentis<br>et viris habuere suas, ad sidera raptim<br>vi propria nituntur opisque haud indiga nostrae.<br>Nec minus interea fetu nemus omne gravescit<br>sanguineisque inculta rubent aviaria bacis.<br>Tondentur cytisi, taedas silva alta ministrat,<br>pascunturque ignes nocturni et lumina fundunt.<br>Et dubitant homines serere atque inpendere curam<br>quid maiora sequar? — -salices humilesque genestae<br>aut illae pecori frondem aut pastoribus umbram<br>Sufficiunt saepemque satis et pabula melli — -<br>et iuvat undantem buxo spectare Cytorum<br>naryciaeque picis lucos, iuvat arva videre<br>non rastris, hominum non ulli obnoxia curae.<br>Ipsae Caucasio steriles in vertice silvae,<br>quas animosi Euri adsidue franguntque feruntque,<br>dant alios aliae fetus, dant utile lignum<br>navigiis pinus, domibus cedrumque cupressosque.<br>Hinc radios trivere rotis, hinc tympana plaustris<br>agricolae et pandas ratibus posuere carinas,<br>viminibus salices fecundae, frondibus ulmi,<br>at myrtus validis hastilibus et bona bello<br>cornus, Ituraeos taxi torquentur in arcus.<br>Nec tiliae leves aut torno rasile buxum<br>non formam accipiunt ferroque cavantur acuto.<br>Nec non et torrentem undam levis innatat alnus,<br>missa Pado; nec non et apes examina condunt<br>corticibusque cavis vitiosaeque ilicis alvo.<br>Quid memorandum aeque Baccheia dona tulerunt<br>Bacchus et ad culpam causas dedit; ille furentis<br>centauros leto domuit, Rhoetumque Pholumque<br>et magno Hylaeum Lapithis cratere minantem.","st":"2"},{"sp":"N","t":"O fortunatos nimium, sua si bona norint,<br>agricolas! quibus ipsa procul discordibus armis<br>fundit humo facilem victum iustissima tellus.<br>Si non ingentem foribus domus alta superbis<br>mane salutantum totis vomit aedibus undam,<br>nec varios inhiant pulchra testudine postis<br>inlusasque auro vestes Ephyreiaque aera,<br>alba neque Assyrio fucatur lana veneno<br>nec casia liquidi corrumpitur usus olivi:<br>at secura quies et nescia fallere vita,<br>dives opum variarum, at latis otia fundis — -<br>speluncae vivique lacus et frigida Tempe<br>mugitusque boum mollesque sub arbore somni — -<br>non absunt; illic saltus ac lustra ferarum<br>et patiens operum exiguoque adsueta iuventus,<br>sacra deum sanctique patres; extrema per illos<br>iustitia excedens terris vestigia fecit.","st":"2"},{"sp":"N","t":"Me vero primum dulces ante omnia Musae,<br>quarum sacra fero ingenti percussus amore,<br>accipiant caelique vias et sidera monstrent,<br>defectus solis varios lunaeque labores;<br>unde tremor terris, qua vi maria alta tumescant<br>obicibus ruptis rursusque in se ipsa residant,<br>quid tantum Oceano properent se tinguere soles<br>hiberni, vel quae tardis mora noctibus obstet.<br>Sin, has ne possim naturae accedere partis,<br>frigidus obstiterit circum praecordia sanguis:<br>rura mihi et rigui placeant in vallibus amnes,<br>flumina amem silvasque inglorius. O ubi campi<br>Spercheosque et virginibus bacchata Lacaenis<br>Taygeta! O, qui me gelidis convallibus Haemi<br>sistat et ingenti ramorum protegat umbra!<br>Felix, qui potuit rerum cognoscere causas,<br>atque metus omnis et inexorabile fatum<br>subiecit pedibus strepitumque Acherontis avari.<br>Fortunatus et ille, deos qui novit agrestis,<br>panaque Silvanumque senem Nymphasque sorores:<br>illum non populi fasces, non purpura regum<br>flexit et infidos agitans discordia fratres<br>aut coniurato descendens Dacus ab Histro,<br>non res Romanae perituraque regna; neque ille<br>aut doluit miserans inopem aut invidit habenti<br>quos rami fructus, quos ipsa volentia rura<br>sponte tulere sua, carpsit; nec ferrea iura<br>insanumque forum aut populi tabularia vidit.<br>sollicitant alii remis freta caeca ruuntque<br>in ferrum, penetrant aulas et limina regum;<br>hic petit excidiis urbem miserosque Penatis,<br>ut gemma bibat et Sarrano dormiat ostro;<br>condit opes alius defossoque incubat auro;<br>hic stupet attonitus rostris; hunc plausus hiantem<br>per cuneos — -geminatus enim plebisque patrumque — -<br>corripuit; gaudent perfusi sanguine fratrum,<br>exsilioque domos et dulcia limina mutant<br>atque alio patriam quaerunt sub sole iacentem.<br>Agricola incurvo terram dimovit aratro:<br>hinc anni labor, hinc patriam parvosque nepotes<br>sustinet, hinc armenta boum meritosque iuvencos.<br>Nec requies, quin aut pomis exuberet annus<br>aut fetu pecorum aut cerealis mergite culmi,<br>proventuque oneret sulcos atque horrea vincat.<br>Venit hiems: teritur Sicyonia baca trapetis,<br>glande sues laeti redeunt, dant arbuta silvae;<br>et varios ponit fetus autumnus et alte<br>mitis in apricis coquitur vindemia saxis.<br>Interea dulces pendent circum oscula nati,<br>casta pudicitiam servat domus, ubera vaccae<br>lactea demittunt pinguesque in gramine laeto<br>inter se adversis luctantur cornibus haedi.<br>Ipse dies agitat festos fususque per herbam,<br>ignis ubi in medio et socii cratera coronant,<br>te libans, Lenaee, vocat pecorisque magistris<br>velocis iaculi certamina ponit in ulmo,<br>corporaque agresti nudant praedura palaestrae.<br>Hanc olim veteres vitam coluere Sabini,<br>hanc Remus et frater, sic fortis Etruria crevit<br>scilicet et rerum facta est pulcherrima Roma,<br>septemque una sibi muro circumdedit arces.<br>Ante etiam sceptrum Dictaei regis et ante<br>inpia quam caesis gens est epulata iuvencis,<br>aureus hanc vitam in terris Saturnus agebat;<br>necdum etiam audierant inflari classica, necdum<br>inpositos duris crepitare incudibus enses.<br>Sed nos inmensum spatiis confecimus aequor,<br>et iam tempus equum fumantia solvere colla.","st":"2"},{"sp":"HDR","t":"Liber III","st":"3"},{"sp":"N","t":"Te quoque, magna Pales, et te memorande canemus<br>pastor ab Amphryso, vos, silvae amnesque Lycaei.<br>Cetera, quae vacuas tenuissent carmine mentes,<br>omnia iam volgata: quis aut Eurysthea durum<br>aut inlaudati nescit Busiridis aras?<br>Cui non dictus Hylas puer et Latonia Delos<br>Hippodameque umeroque Pelops insignis eburno,<br>acer equis? Temptanda via est, qua me quoque possim<br>tollere humo victorque virum volitare per ora.<br>Primus ego in patriam mecum, modo vita supersit,<br>Aonio rediens deducam vertice Musas;<br>primus Idumaeas referam tibi, Mantua, palmas,<br>et viridi in campo templum de marmore ponam<br>propter aquam. Tardis ingens ubi flexibus errat<br>Mincius et tenera praetexit arundine ripas.<br>In medio mihi Caesar erit templumque tenebit:<br>illi victor ego et Tyrio conspectus in ostro<br>centum quadriiugos agitabo ad flumina currus.<br>Cuncta mihi Alpheum linquens lucosque Molorchi<br>cursibus et crudo decernet Graecia caestu.<br>Ipse caput tonsae foliis ornatus olivae<br>dona feram. Iam nunc sollemnis ducere pompas<br>ad delubra iuvat caesosque videre iuvencos,<br>vel scaena ut versis discedat frontibus utque<br>purpurea intexti tollant aulaea Britanni.<br>In foribus pugnam ex auro solidoque elephanto<br>Gangaridum faciam victorisque arma Quirini,<br>atque hic undantem bello magnumque fluentem<br>Nilum ac navali surgentis aere columnas.<br>Addam urbes Asiae domitas pulsumque Niphaten<br>fidentemque fuga Parthum versisque sagittis,<br>et duo rapta manu diverso ex hoste tropaea<br>bisque triumphatas utroque ab litore gentes.<br>Stabunt et Parii lapides, spirantia signa,<br>Assaraci proles demissaeque ab Iove gentis<br>nomina, Trosque parens et Troiae Cynthius auctor.<br>Invidia infelix Furias amnemque severum<br>Cocyti metuet tortosque Ixionis anguis<br>immanemque rotam et non exsuperabile saxum.<br>Interea Dryadum silvas saltusque sequamur<br>intactos, tua, Maecenas, haud mollia iussa.<br>Te sine nil altum mens incohat; en age segnis<br>rumpe moras; vocat ingenti clamore Cithaeron<br>Taygetique canes domitrixque Epidaurus equorum<br>et vox adsensu nemorum ingeminata remugit.<br>Mox tamen ardentis accingar dicere pugnas<br>Caesaris et nomen fama tot ferre per annos,<br>Tithoni prima quot abest ab origine Caesar.","st":"3"},{"sp":"N","t":"Seu quis Olympiacae miratus praemia palmae<br>pascit equos seu quis fortis ad aratra iuvencos,<br>corpora praecipue matrum legat. Optuma torvae<br>forma bovis, cui turpe caput, cui plurima cervix,<br>et crurum tenus a mento palearia pendent;<br>tum longo nullus lateri modus; omnia magna,<br>pes etiam; et camuris hirtae sub cornibus aures.<br>Nec mihi displiceat maculis insignis et albo,<br>aut iuga detractans interdumque aspera cornu<br>et faciem tauro propior, quaeque ardua tota,<br>et gradiens ima verrit vestigia cauda,<br>Aetas Lucinam iustosque pati hymenaeos<br>desinit ante decem, post quattuor incipit annos;<br>cetera nec feturae habilis nec fortis aratris.<br>Interea, superat gregibus dum laeta iuventas,<br>solve mares; mitte in Venerem pecuaria primus,<br>atque aliam ex alia generando suffice prolem.<br>Optuma quaeque dies miseris mortalibus aevi<br>prima fugit; subeunt morbi tristisque senectus<br>et labor, et durae rapit inclementia mortis.<br>Semper erunt, quarum mutari corpora malis:<br>semper enim refice ac, ne post amissa requiras,<br>ante veni et subolem armento sortire quotannis.","st":"3"},{"sp":"N","t":"Nec non et pecori est idem dilectus equino.<br>Tu modo, quos in spem statues submittere gentis,<br>praecipuum iam inde a teneris impende laborem.<br>Continuo pecoris generosi pullus in arvis<br>altius ingreditur et mollia crura reponit;<br>primus et ire viam et fluvios temptare minaces<br>audet et ignoto sese committere ponti<br>nec vanos horret strepitus. Illi ardua cervix<br>argutumque caput, brevis alvus obesaque terga,<br>luxuriatque toris animosum pectus. Honesti<br>spadices glaucique, color deterrimus albis<br>et gilvo. Tum, si qua sonum procul arma dedere<br>stare loco nescit, micat auribus et tremit artus<br>collectumque premens volvit sub naribus ignem.<br>Densa iuba, et dextro iactata recumbit in armo;<br>at duplex agitur per lumbos spina, cavatque<br>tellurem et solido graviter sonat ungula cornu.<br>Talis Amyclaei domitus Pollucis habenis<br>Cyllarus et, quorum Grai meminere poetae,<br>Martis equi biiuges et magni currus Achilli.<br>Talis et ipse iubam cervice effundit equina<br>coniugis adventu pernix Saturnus et altum<br>Pelion hinnitu fugiens implevit acuto.","st":"3"},{"sp":"N","t":"Hunc quoque, ubi aut morbo gravis aut iam segnior annis<br>deficit, abde domo nec turpi ignosce senectae.<br>frigidus in Venerem senior, frustraque laborem<br>ingratum trahit, et, si quando ad proelia ventum est,<br>ut quondam in stipulis magnus sine viribus ignis,<br>incassum furit. Ergo animos aevumque notabis<br>praecipue; hinc alias artis prolemque parentum<br>et quis cuique dolor victo, quae gloria palmae.<br>Nonne vides, cum praecipiti certamine campum<br>corripuere ruuntque effusi carcere currus,<br>cum spes arrectae iuvenum, exsultantiaque haurit<br>corda pavor pulsans? Illi instant verbere torto<br>et proni dant lora, volat vi fervidus axis;<br>iamque humiles, iamque elati sublime videntur<br>aera per vacuum ferri atque adsurgere in auras;<br>nec mora nec requies; at fulvae nimbus harenae<br>tollitur, umescunt spumis flatuque sequentum:<br>tantus amor laudum, tantae est victoria curae.<br>Primus Erichthonius currus et quattuor ausus<br>iungere equos rapidusque rotis insistere victor<br>Frena Pelethronii Lapithae gyrosque dedere<br>impositi dorso atque equitem docuere sub armis<br>insultare solo et gressus glomerare superbos.<br>Aequus uterque labor, aeque iuvenemque magistri<br>exquirunt calidumque animis et cursibus acrem,<br>quamvis saepe fuga versos ille egerit hostis<br>et patriam Epirum referat fortisque Mycenas<br>Neptunique ipsa deducat origine gentem.","st":"3"},{"sp":"N","t":"His animadversis instant sub tempus et omnis<br>impendunt curas denso distendere pingui,<br>quem legere ducem et pecori dixere maritum;<br>florentisque secant herbas fluviosque ministrant<br>farraque, ne blando nequeat superesse labori<br>invalidique patrum referant ieiunia nati.<br>Ipsa autem macie tenuant armenta volentes,<br>atque, ubi concubitus primos iam nota voluptas<br>sollicitat, frondesque negant et fontibus arcent.<br>Saepe etiam cursu quatiunt et sole fatigant,<br>cum graviter tunsis gemit area frugibus et cum<br>surgentem ad Zephyrum paleae iactantur inanes.<br>Hoc faciunt, nimio ne luxu obtunsior usus<br>sit genitali arvo et sulcos oblimet inertis,<br>sed rapiat sitiens Venerem interiusque recondat.","st":"3"},{"sp":"N","t":"Rursus cura patrum cadere et succedere matrum<br>incipit. Exactis gravidae cum mensibus errant,<br>non illas gravibus quisquam iuga ducere plaustris,<br>non saltu superare viam sit passus et acri<br>carpere prata fuga fluviosque innare rapacis.<br>Saltibus in vacuis pascunt et plena secundum<br>flumina, muscus ubi et viridissima gramine ripa,<br>speluncaeque tegant et saxea procubet umbra.<br>Est lucos Silari circa ilicibusque; virentem<br>plurimus Alburnum volitans, cui nomen asilo<br>Romanum est, oestrum Grai vertere vocantes,<br>asper, acerba sonans, quo tota exterrita silvis<br>diffugiunt armenta; furit mugitibus aether<br>concussus silvaeque et sicci ripa Tanagri.<br>Hoc quondam monstro horribilis exercuit iras<br>Inachiae Iuno pestem meditata iuvencae.<br>Hunc quoque, nam mediis fervoribus acrior instat,<br>arcebis gravido pecori, armentaque pasces<br>sole recens orto aut noctem ducentibus astris.","st":"3"},{"sp":"N","t":"Post partum cura in vitulos traducitur omnis,<br>continuoque notas et nomina gentis inurunt<br>et quos aut pecori malint submittere habendo<br>aut aris servare sacros aut scindere terram<br>et campum horrentem fractis invertere glaebis.<br>Cetera pascuntur viridis armenta per herbas:<br>Tu quos ad studium atque usum formabis agrestem,<br>iam vitulos hortare viamque insiste domandi,<br>dum faciles animi iuvenum, dum mobilis aetas.<br>Ac primum laxos tenui de vimine circlos<br>cervici subnecte; dehinc, ubi libera colla<br>servitio adsuerint, ipsis e torquibus aptos<br>iunge pares et coge gradum conferre iuvencos;<br>atque illis iam saepe rotae ducantur inanes<br>per terram et summo vestigia pulvere signent;<br>post valido nitens sub pondere faginus axis<br>instrepat et iunctos temo trahat aereus orbes.<br>Interea pubi indomitae non gramina tantum<br>nec vescas salicum frondes ulvamque palustrem,<br>sed frumenta manu carpes sata; nec tibi fetae<br>more patrum nivea implebunt mulctraria vaccae,<br>sed tota in dulcis consument ubera natos.","st":"3"},{"sp":"N","t":"Sin ad bella magis studium turmasque ferocis,<br>aut Alphea rotis praelabi flumina Pisae<br>et Iovis in luco currus agitare volantis:<br>primus equi labor est, animos atque arma videre<br>bellantum lituosque pati tractuque gementem<br>ferre rotam et stabulo frenos audire sonantis;<br>tum magis atque magis blandis gaudere magistri<br>laudibus et plausae sonitum cervicis amare.<br>Atque haec iam primo depulsus ab ubere matris<br>audeat, inque vicem det mollibus ora capistris<br>invalidus etiamque tremens, etiam inscius aevi.<br>At tribus exactis ubi quarta accesserit aestas,<br>carpere mox gyrum incipiat gradibusque sonare<br>compositis sinuetque alterna volumina crurum<br>sitque laboranti similis; tum cursibus auras,<br>tum vocet, ac per aperta volans ceu liber habenis<br>aequora vix summa vestigia ponat harena;<br>qualis Hyperboreis Aquilo cum densus ab oris<br>incubuit, Scythiaeque hiemes atque arida differt<br>nubila: tum segetes altae campique natantes<br>lenibus horrescunt flabris summaeque sonorem<br>dant silvae longique urgent ad litora fluctus;<br>ille volat simul arva fuga, simul aequora verrens<br>Hinc vel ad Elei metas et maxuma campi<br>sudabit spatia et spumas aget ore cruentas,<br>Belgica vel molli melius feret esseda collo.<br>Tum demum crassa magnum farragine corpus<br>crescere iam domitis sinito: namque ante domandum<br>ingentis tollent animos prensique negabunt<br>verbera lenta pati et duris parere lupatis.","st":"3"},{"sp":"N","t":"Sed non ulla magis viris industria firmat,<br>quam Venerem et caeci stimulos avertere amoris,<br>sive boum sive est cui gratior usus equorum.<br>Atque ideo tauros procul atque in sola relegant<br>pascua post montem oppositum et trans flumina lata,<br>aut intus clausos satura ad praesepia servant.<br>Carpit enim viris paulatim uritque videndo<br>femina nec nemorum patitur meminisse nec herbae<br>dulcibus illa quidem inlecebris, et saepe superbos<br>cornibus inter se subigit decernere amantis.<br>Pascitur in magna Sila formosa iuvenca:<br>illi alternantes multa vi proelia miscent<br>volneribus crebris, lavit ater corpora sanguis,<br>versaque in obnixos urguentur cornua vasto<br>cum gemitu, reboant silvaeque et longus Olympus<br>Nec mos bellantis una stabulare, sed alter<br>victus abit longeque ignotis exulat oris,<br>multa gemens ignominiam plagasque superbi<br>victoris, tum, quos amisit inultus, amores;<br>et stabula aspectans regnis excessit avitis.<br>Ergo omni cura viris exercet et inter<br>dura iacet pernix instrato saxa cubili<br>frondibus hirsutis et carice pastus acuta,<br>et temptat sese atque irasci in cornua discit<br>arboris obnixus trunco ventosque lacessit<br>ictibus et sparsa ad pugnam proludit harena.<br>Post ubi collectum robur viresque refectae<br>signa movet praecepsque oblitum fertur in hostem:<br>fluctus uti medio coepit cum albescere ponto<br>longius ex altoque sinum trahit, utque volutus<br>ad terras immane sonat per saxa neque ipso<br>monte minor procumbit, at ima exaestuat unda<br>verticibus nigramque alte subiectat harenam.","st":"3"},{"sp":"N","t":"Omne adeo genus in terris hominumque ferarumque,<br>et genus aequoreum, pecudes pictaeque volucres,<br>in furias. ignemque ruunt. Amor omnibus idem.<br>Tempore non alio catulorum oblita leaena<br>saevior erravit campis, nec funera volgo<br>tam multa informes ursi stragemque dedere<br>per silvas; tum saevus aper, tum pessima tigris;<br>heu male tum Libyae solis erratur in agris.<br>Nonne vides, ut tota tremor pertemptet equorum<br>corpora, si tantum notas odor attulit auras?<br>Ac neque eos iam frena virum neque verbera saeva<br>non scopuli rupesque cavae atque obiecta retardant<br>flumina correptosque unda torquentia montis.<br>Ipse ruit dentesque Sabellicus exacuit sus<br>et pede prosubigit terram, fricat arbore costas<br>atque hinc atque illinc umeros ad volnera durat.<br>Quid iuvenis, magnum cui versat in ossibus ignem<br>durus amor? Nempe abruptis turbata procellis<br>nocte natat caeca serus freta; quem super ingens<br>porta tonat caeli et scopulis inlisa reclamant<br>aequora; nec miseri possunt revocare parentes<br>nec moritura super crudeli funere virgo.<br>Quid lynces Bacchi variae et genus acre luporum<br>atque canum? Quid, quae imbelles dant proelia cervi?<br>Scilicet ante omnis furor est insignis equarum;<br>et mentem Venus ipsa dedit, quo tempore Glauci<br>Potniades malis membra absumpsere quadrigae.<br>Illas ducit amor trans Gargara transque sonantem<br>Ascanium; superant montis et flumina tranant.<br>Continuoque avidis ubi subdita flamma medullis,<br>vere magis, quia vere calor redit ossibus: illae<br>ore omnes versae in Zephyrum stant rupibus altis,<br>exceptantque levis auras et saepe sine ullis<br>coniugiis vento gravidae, mirabile dictu,<br>saxa per et scopulos et depressas convallis<br>diffugiunt, non, Eure, tuos, neque solis ad ortus,<br>in Borean caurumque, aut unde nigerrimus auster<br>nascitur et pluvio contristat frigore caelum.<br>Hic demum, hippomanes vero quod nomine dicunt<br>pastores, lentum destillat ab inguine virus,<br>hippomanes, quod saepe malae legere novercae<br>miscueruntque herbas et non innoxia verba.","st":"3"},{"sp":"N","t":"Sed fugit interea, fugit inreparabile tempus,<br>singula dum capti circumvectamur amore.<br>Hoc satis armentis: superat pars altera curae,<br>lanigeros agitare greges hirtasque capellas.<br>Hic labor, hinc laudem fortes sperate coloni.<br>Nec sum animi dubius, verbis ea vincere magnum<br>quam sit, et angustis hunc addere rebus honorem;<br>sed me Parnasi deserta per ardua dulcis<br>raptat amor; iuvat ire iugis, qua nulla priorum<br>Castaliam molli devertitur orbita clivo.<br>Nunc, veneranda Pales, magno nunc ore sonandum","st":"3"},{"sp":"N","t":"Incipiens stabulis edico in mollibus herbam<br>carpere ovis, dum mox frondosa reducitur aestas,<br>et multa duram stipula filicumque maniplis<br>sternere subter humum, glacies ne frigida laedat<br>molle pecus scabiemque ferat turpisque podagras.<br>Post hinc digressus iubeo frondentia capris<br>arbuta sufficere et fluvios praebere recentis<br>et stabula a ventis hiberno opponere soli<br>ad medium conversa diem, cum frigidus olim<br>iam cadit extremoque inrorat Aquarius anno.<br>Haec quoque non cura nobis leviore tuendae,<br>nec minor usus erit, quamvis Milesia magno<br>vellera mutentur Tyrios incocta rubores:<br>densior hinc suboles, hinc largi copia lactis;<br>quam magis exhausto spumaverit ubere mulctra,<br>laeta magis pressis manabunt flumina mammis.<br>Nec minus interea barbas incanaque menta<br>Cinyphii tondent hirci saetasque comantis<br>usum in castrorum et miseris velamina nautis.<br>Pascuntur vero silvas et summa Lycaei<br>horrentisque rubos et amantis ardua dumos:<br>atque ipsae memores redeunt in tecta suosque<br>ducunt et gravido superant vix ubere limen.<br>Ergo omni studio glaciem ventosque nivalis<br>quo minor est illis curae mortalis egestas,<br>avertes victumque feres et virgea laetus<br>pabula, nec tota claudes faenilia bruma.<br>At vero Zephyris cum laeta vocantibus aestas<br>in saltus utrumque gregem atque in pascua mittet,<br>Luciferi primo cum sidere frigida rura<br>carpamus, dum mane novum, dum gramina canent,<br>et ros in tenera pecori gratissimus herba.<br>Inde ubi quarta sitim caeli collegerit hora<br>et cantu querulae rumpent arbusta cicadae,<br>ad puteos aut alta greges ad stagna iubebo<br>currentem ilignis potare canalibus undam;<br>aestibus at mediis umbrosam exquirere vallem,<br>sicubi magna Iovis antiquo robore quercus<br>ingentis tendat ramos, aut sicubi nigrum<br>ilicibus crebris sacra nemus accubet umbra;<br>tum tenuis dare rursus aquas et pascere rursus<br>solis ad occasum, cum frigidus aera vesper<br>temperat et saltus reficit iam roscida luna<br>litoraque alcyonem resonant, acalanthida dumi.","st":"3"},{"sp":"N","t":"Quid tibi pastores Libyae, quid pascua versu<br>prosequar et raris habitata mapalia tectis?<br>Saepe diem noctemque et totum ex ordine mensem<br>pascitur itque pecus longa in deserta sine ullis<br>hospitiis: tantum campi iacet. Omnia secum<br>armentarius Afer agit, tectumque laremque<br>armaque Amyclaeumque canem Cressamque pharetram;<br>non secus ac patriis acer Romanus in armis<br>iniusto sub fasce viam cum carpit et hosti<br>ante expectatum positis stat in agmine castris.","st":"3"},{"sp":"N","t":"At non, qua Scythiae gentes Maeotiaque unda,<br>turbidus et torquens flaventis Hister harenas,<br>quaque redit medium Rhodope porrecta sub axem.<br>Illic clausa tenent stabulis armenta, neque ullae<br>aut herbae campo apparent aut arbore frondes;<br>sed iacet aggeribus niveis informis et alto<br>terra gelu late septemque adsurgit in ulnas.<br>Semper hiemps, semper spirantes frigora cauri.<br>Tum Sol pallentis haud umquam discutit umbras,<br>nec cum invectus equis altum petit aethera, nec cum<br>praecipitem Oceani rubro lavit aequore currum.<br>Concrescunt subitae currenti in flumine crustae<br>undaque iam tergo ferratos sustinet orbis,<br>puppibus illa prius, patulis nunc hospita plaustris;<br>aeraque dissiliunt vulgo vestesque rigescunt<br>indutae caeduntque securibus umida vina<br>et totae solidam in glaciem vertere lacunae<br>stiriaque impexis induruit horrida barbis.<br>Interea toto non setius aere ninguit:<br>intereunt pecudes, stant circumfusa pruinis<br>corpora magna boum, confertoque agmine cervi<br>torpent mole nova et summis vix cornibus extant.<br>Hos non immissis canibus, non cassibus ullis<br>puniceaeve agitant pavidos formidine pennae,<br>sed frustra oppositum trudentis pectore montem<br>comminus obtruncant ferro graviterque rudentis<br>caedunt et magno laeti clamore reportant.<br>Ipsi in defossis specubus secura sub alta<br>otia agunt terra congestaque robora totasque<br>advolvere focis ulmos ignique dedere.<br>Hic noctem ludo ducunt et pocula laeti<br>fermento atque acidis imitantur vitea sorbis.<br>Talis Hyperboreo septem subiecta trioni<br>gens effrena virum Rhiphaeo tunditur euro<br>et pecudum fulvis velatur corpora saetis.","st":"3"},{"sp":"N","t":"Si tibi lanitium curae, primum aspera silva,<br>lappaeque tribolique, absint; fuge pabula laeta;<br>Continuoque greges villis lege mollibus albos.<br>Illum autem, quamvis aries sit candidus ipse,<br>nigra subest udo tantum cui lingua palato,<br>reice, ne maculis infuscet vellera pullis<br>nascentum, plenoque alium circumspice campo.<br>Munere sic niveo lanae, si credere dignum est,<br>Pan deus Arcadiae captam te, Luna, fefellit<br>in nemora alta vocans; nec tu aspernata vocantem.","st":"3"},{"sp":"N","t":"At cui lactis amor, cytisum lotosque frequentis<br>ipse manu salsasque ferat praesepibus herbas.<br>Hinc et amant fluvios magis et magis ubera tendunt<br>et salis occultum referunt in lacte saporem.<br>Multi iam excretos prohibent a matribus haedos<br>primaque ferratis praefigunt ora capistris.<br>Quod surgente die mulsere horisque diurnis,<br>nocte premunt; quod iam tenebris et sole cadente,<br>sub lucem exportant calathis adit oppida pastor;<br>aut parco sale contingunt hiemique reponunt.","st":"3"},{"sp":"N","t":"Nec tibi cura canum fuerit postrema, sed una<br>velocis Spartae catulos acremque Molossum<br>pasce sero pingui. Numquam custodibus illis<br>nocturnum stabulis furem incursusque luporum<br>aut impacatos a tergo horrebis Hiberos.<br>Saepe etiam cursu timidos agitabis onagros<br>et canibus leporem, canibus venabere dammas,<br>saepe volutabris pulsos silvestribus apros<br>latratu turbabis agens montisque per altos<br>ingentem clamore premes ad retia cervum.","st":"3"},{"sp":"N","t":"Disce et odoratam stabulis accendere cedrum<br>galbaneoque agitare gravis nidore chelydros.<br>saepe sub immotis praesepibus aut mala tactu<br>vipera delituit caelumque exterrita fugit,<br>aut tecto adsuetus coluber succedere et umbrae,<br>pestis acerba boum, pecorique aspergere virus,<br>fovit humum. Cape saxa manu, cape robora, pastor,<br>tollentemque minas et sibila colla tumentem<br>deice. Iamque fuga timidum caput abdidit alte,<br>cum medii nexus extremaeque agmina caudae<br>solvuntur, tardosque trahit sinus ultimus orbis.<br>Est etiam ille malus Calabris in saltibus anguis,<br>squamea convolvens sublato pectore terga<br>atque notis longam maculosus grandibus alvum<br>qui, dum amnes ulli rumpuntur fontibus et dum<br>vere madent udo terrae ac pluvialibus austris<br>stagna colit, ripisque habitans hic piscibus atram<br>improbus ingluviem ranisque loquacibus explet;<br>postquam exusta palus, terraeque ardore dehiscunt,<br>exsilit in siccum et flammantia lumina torquens<br>saevit agris asperque siti atque exterritus aestu.<br>Ne mihi tum mollis sub divo carpere somnos<br>neu dorso nemoris libeat iacuisse per herbas,<br>cum positis novus exuviis nitidusque iuventa<br>volvitur, aut catulos tectis aut ova relinquens<br>arduus ad solem et linguis micat ore trisulcis.","st":"3"},{"sp":"N","t":"Morborum quoque te causas et signa docebo.<br>Turpis ovis temptat scabies, ubi frigidus imber<br>altius ad vivum persedit et horrida cano<br>bruma gelu, vel cum tonsis inlotus adhaesit<br>sudor et hirsuti secuerunt corpora vepres.<br>Dulcibus idcirco fluviis pecus omne magistri<br>perfundunt, udisque aries in gurgite villis<br>mersatur missusque secundo defluit amni;<br>aut tonsum tristi contingunt corpus amurca<br>et spumas miscent argenti et sulfura viva<br>Idaeasque pices et pinguis unguine ceras<br>scillamque elleborosque gravis nigrumque bitumen.<br>Non tamen ulla magis praesens fortuna laborum est,<br>quam si quis ferro potuit rescindere summum<br>ulceris os: alitur vitium vivitque tegendo,<br>dum medicas adhibere manus ad volnera pastor<br>abnegat et meliora deos sedet omnia poscens.<br>Quin etiam, ima dolor balantum lapsus ad ossa<br>cum furit atque artus depascitur arida febris,<br>profuit incensos aestus avertere et inter<br>ima ferire pedis salientem sanguine venam,<br>Bisaltae quo more solent acerque Gelonus;<br>cum fugit in Rhodopen atque in deserta Getarum<br>et lac concretum cum sanguine potat equino.<br>Quam procul aut molli succedere saepius umbrae<br>videris aut summas carpentem ignavius herbas<br>extremamque sequi aut medio procumbere campo<br>pascentem et serae solam decedere nocti:<br>continuo culpam ferro compesce, prius quam<br>dira per incautum serpant contagia volgus.<br>Non tam creber agens hiemem ruit aequore turbo,<br>quam multae pecudum pestes. Nec singula morbi<br>corpora corripiunt, sed tota aestiva repente,<br>spemque gregemque simul cunctamque ab origine gentem.<br>Tum sciat, aerias Alpis et Norica si quis<br>castella in tumulis et Iapydis arva Timavi<br>nunc quoque post tanto videat desertaque regna<br>pastorum et longe saltus lateque vacantis.","st":"3"},{"sp":"N","t":"Hic quondam morbo caeli miseranda coorta est<br>tempestas totoque autumni incanduit aestu<br>et genus omne neci pecudum dedit, omne ferarum,<br>corrupitque lacus, infecit pabula tabo.<br>Nec via mortis erat simplex, sed ubi ignea venis<br>omnibus acta sitis miseros adduxerat artus,<br>rursus abundabat fluidus liquor omniaque in se<br>ossa minutatim morbo collapsa trahebat.<br>Saepe in honore deum medio stans hostia ad aram<br>lanea dum nivea circumdatur infula vitta,<br>inter cunctantis cecidit moribunda ministros.<br>Aut si quam ferro mactaverat ante sacerdos<br>inde neque impositis ardent altaria fibris<br>nec responsa potest consultus reddere vates,<br>ac vix suppositi tinguntur sanguine cultri<br>summaque ieiuna sanie infuscatur harena.<br>Hinc laetis vituli volgo moriuntur in herbis<br>et dulcis animas plena ad praesepia reddunt;<br>hinc canibus blandis rabies venit et quatit aegros<br>tussis anhela sues ac faucibus angit obesis.<br>Labitur infelix studiorum atque immemor herbae<br>victor equus fontisque avertitur et pede terram<br>crebra ferit; demissae aures, incertus ibidem<br>sudor et ille quidem morituris frigidus, aret<br>pellis et ad tactum tractanti dura resistit.<br>Haec ante exitium primis dant signa diebus;<br>sin in processu coepit crudescere morbus,<br>tum vero ardentes oculi atque attractus ab alto<br>spiritus, interdum gemitu gravis, imaque longo<br>ilia singultu tendunt, it naribus ater<br>sanguis et obsessas fauces premit aspera lingua.<br>Profuit inserto latices infundere cornu<br>Lenaeos; ea visa salus morientibus una;<br>mox erat hoc ipsum exitio, furiisque refecti<br>ardebant ipsique suos iam morte sub aegra,<br>di meliora piis erroremque hostibus illum,<br>discissos nudis laniabant dentibus artus.<br>Ecce autem duro fumans sub vomere taurus<br>concidit et mixtum spumis vomit ore cruorem<br>extremosque ciet gemitus. It tristis arator<br>maerentem abiungens fraterna morte iuvencum,<br>atque opere in medio defixa relinquit aratra.<br>Non umbrae altorum nemorum, non mollia possunt<br>prata movere animum, non qui per saxa volutus<br>purior electro campum petit amnis; at ima<br>solvuntur latera atque oculos stupor urguet inertis<br>ad terramque fluit devexo pondere cervix.<br>Quid labor aut benefacta iuvant? Quid vomere terras<br>invertisse gravis? Atqui non Massica Bacchi<br>munera, non illis epulae nocuere repostae:<br>frondibus et victu pascuntur simplicis herbae,<br>pocula sunt fontes liquidi atque exercita cursu<br>flumina, nec somnos abrumpit cura salubris.<br>Tempore non alio dicunt regionibus illis<br>quaesitas ad sacra boves Iunonis et uris<br>imparibus ductos alta ad donaria currus.<br>Ergo aegre rastris terram rimantur et ipsis<br>unguibus infodiunt fruges montisque per altos<br>contenta cervice trahunt stridentia plaustra.<br>Non lupus insidias explorat ovilia circum<br>nec gregibus nocturnus obambulat; acrior illum<br>cura domat; timidi dammae cervique fugaces<br>nunc interque canes et circum tecta vagantur.<br>Iam maris immensi prolem et genus omne natantum<br>litore in extremo, ceu naufraga corpora, fluctus<br>proluit; insolitae fugiunt in flumina phocae.<br>Interit et curvis frustra defensa latebris<br>vipera et attoniti squamis adstantibus hydri.<br>Ipsis est aer avibus non aequus et illae<br>praecipites alta vitam sub nube relinquunt.<br>Praeterea iam nec mutari pabula refert<br>artes nocent quaesitaeque; cessere magistri<br>Phillyrides Chiron Amythaoniusque Melampus.<br>Saevit et in lucem Stygiis emissa tenebris<br>pallida Tisiphone Morbos agit ante Metumque,<br>inque dies avidum surgens caput altius effert:<br>Balatu pecorum et crebris mugitibus amnes<br>arentesque sonant ripae collesque supini:<br>Iamque catervatim dat stragem atque aggerat ipsis<br>in stabulis turpi dilapsa cadavera tabo<br>donec humo tegere ac foveis abscondere discunt.<br>Nam neque erat coriis usus nec viscera quisquam<br>aut undis abolere potest aut vincere flamma;<br>ne tondere quidem morbo inluvieque peresa<br>vellera nec telas possunt attingere putris;<br>verum etiam invisos si quis temptarat amictus,<br>ardentes papulae atque immundus olentia sudor<br>membra sequebatur nec longo deinde moranti<br>tempore contactos artus sacer ignis edebat.","st":"3"},{"sp":"HDR","t":"Liber IV","st":"4"},{"sp":"N","t":"Protinus aerii mellis caelestia dona<br>exsequar: hanc etiam, Maecenas, adspice partem.<br>Admiranda tibi levium spectacula rerum<br>magnanimosque duces totiusque ordine gentis<br>mores et studia et populos et proelia dicam.<br>In tenui labor; at tenuis non gloria, si quem<br>numina laeva sinunt auditque vocatus Apollo.","st":"4"},{"sp":"N","t":"Principio sedes apibus statioque petenda,<br>quo neque sit ventis aditus — -nam pabula venti<br>ferre domum prohibent — -neque oves haedique petulci<br>floribus insultent aut errans bucula campo<br>decutiat rorem et surgentes atterat herbas.<br>Absint et picti squalentia terga lacerti<br>pinguibus a stabulis meropesque aliaeque volucres<br>et manibus Procne pectus signata cruentis;<br>omnia nam late vastant ipsasque volantes<br>ore ferunt dulcem nidis immitibus escam.<br>At liquidi fontes et stagna virentia musco<br>adsint et tenuis fugiens per gramina rivus,<br>palmaque vestibulum aut ingens oleaster inumbret,<br>ut, cum prima novi ducent examina reges<br>vere suo ludetque favis emissa iuventus,<br>vicina invitet decedere ripa calori,<br>obviaque hospitiis teneat frondentibus arbos.<br>In medium, seu stabit iners seu profluet umor,<br>transversas salices et grandia conice saxa,<br>pontibus ut crebris possint consistere et alas<br>pandere ad aestivum solem, si forte morantes<br>sparserit aut praeceps Neptuno immerserit Eurus.<br>Haec circum casiae virides et olentia late<br>serpylla et graviter spirantis copia thymbrae<br>floreat inriguumque bibant violaria fontem.<br>Ipsa autem, seu corticibus tibi suta cavatis,<br>seu lento fuerint alvaria vimine texta,<br>angustos habeant aditus: nam frigore mella<br>cogit hiems, eademque calor liquefacta remittit.<br>Utraque vis apibus pariter metuenda; neque illae<br>nequiquam in tectis certatim tenuia cera<br>spiramenta linunt fucoque et floribus oras<br>explent collectumque haec ipsa ad munera gluten<br>et visco et Phrygiae servant pice lentius Idae.<br>Saepe etiam effossis, si vera est fama, latebris<br>sub terra fovere larem, penitusque repertae<br>pumicibusque cavis exesaeque arboris antro.<br>Tu tamen et levi rimosa cubilia limo<br>ungue fovens circum et raras superinice frondes.<br>Neu propius tectis taxum sine, neve rubentes<br>ure foco cancros, altae neu crede paludi,<br>aut ubi odor caeni gravis aut ubi concava pulsu<br>saxa sonant vocisque offensa resultat imago.","st":"4"},{"sp":"N","t":"Quod superest, ubi pulsam hiemem sol aureus egit<br>sub terras caelumque aestiva luce reclusit,<br>illae continuo saltus silvasque peragrant<br>purpureosque metunt flores et flumina libant<br>summa leves. Hinc nescio qua dulcedine laetae<br>progeniem nidosque fovent, hinc arte recentes<br>excudunt ceras et mella tenacia fingunt.<br>Hinc ubi iam emissum caveis ad sidera caeli<br>nare per aestatem liquidam suspexeris agmen<br>obscuramque trahi vento mirabere nubem,<br>contemplator: aquas dulces et frondea semper<br>tecta petunt. Huc tu iussos adsperge sapores,<br>trita melisphylla et cerinthae ignobile gramen,<br>tinnitusque cie et Matris quate cymbala circum.<br>ipsae consident medicatis sedibus, ipsae<br>intima more suo sese in cunabula condent.","st":"4"},{"sp":"N","t":"Sin autem ad pugnam exierint, nam saepe duobus<br>regibus incessit magno discordia motu,<br>continuoque animos vulgi et trepidantia bello<br>corda licet longe praesciscere; namque morantes<br>Martius ille aeris rauci canor increpat et vox<br>auditur fractos sonitus imitata tubarum;<br>tum trepidae inter se coeunt pennisque coruscant<br>spiculaque exacuunt rostris aptantque lacertos<br>et circa regem atque ipsa ad praetoria densae<br>miscentur magnisque vocant clamoribus hostem.<br>Ergo ubi ver nactae sudum camposque patentes,<br>erumpunt portis; concurritur, aethere in alto<br>fit sonitus, magnum mixtae glomerantur in orbem<br>praecipitesque cadunt; non densior aere grando,<br>nec de concussa tantum pluit ilice glandis.<br>ipsi per medias acies insignibus alis<br>ingentes animos angusto in pectore versant,<br>usque adeo obnixi non cedere, dum gravis aut hos<br>aut hos versa fuga victor dare terga subegit.<br>Hi motus animorum atque haec certamina tanta<br>pulveris exigui iactu compressa quiescent.<br>Verum ubi ductores acie revocaveris ambo,<br>deterior qui visus, eum, ne prodigus obsit,<br>dede neci; melior vacua sine regnet in aula.<br>Alter erit maculis auro squalentibus ardens;<br>nam duo sunt genera: hic melior, insignis et ore<br>et rutilis clarus squamis, ille horridus alter<br>desidia latamque trahens inglorius alvum.","st":"4"},{"sp":"N","t":"Ut binae regum facies, ita corpora plebis.<br>Namque aliae turpes horrent, ceu pulvere ab alto<br>cum venit et sicco terram spuit ore viator<br>aridus; elucent aliae et fulgore coruscant<br>ardentes auro et paribus lita corpora guttis.<br>Haec potior suboles, hinc caeli tempore certo<br>dulcia mella premes, nec tantum dulcia, quantum<br>et liquida et durum Bacchi domitura saporem.","st":"4"},{"sp":"N","t":"At cum incerta volant caeloque examina ludunt<br>contemnuntque favos et frigida tecta relinquunt,<br>instabiles animos ludo prohibebis inani.<br>Nec magnus prohibere labor: tu regibus alas<br>eripe; non illis quisquam cunctantibus altum<br>ire iter aut castris audebit vellere signa.<br>Invitent croceis halantes floribus horti<br>et custos furum atque avium cum falce saligna<br>Hellespontiaci servet tutela Priapi.<br>Ipse thymum pinosque ferens de montibus altis<br>tecta serat late circum, cui talia curae;<br>ipse labore manum duro terat, ipse feraces<br>figat humo plantas et amicos inriget imbres.","st":"4"},{"sp":"N","t":"Atque equidem, extremo ni iam sub fine laborum<br>vela traham et terris festinem advertere proram,<br>forsitan et, pingues hortos quae cura colendi<br>ornaret, canerem, biferique rosaria Paesti,<br>quoque modo potis gauderent intiba rivis<br>et virides apio ripae, tortusque per herbam<br>cresceret in ventrem cucumis; nec sera comantem<br>narcissum aut flexi tacuissem vimen acanthi<br>pallentesque hederas et amantes litora myrtos.<br>Namque sub Oebaliae memini me turribus arcis,<br>qua niger umectat flaventia culta Galaesus,<br>Corycium vidisse senem, cui pauca relicti<br>iugera ruris erant, nec fertilis illa iuvencis<br>nec pecori opportuna seges nec commoda Baccho.<br>Hic rarum tamen in dumis olus albaque circum<br>lilia verbenasque premens vescumque papaver<br>regum aequabat opes animis seraque revertens<br>nocte domum dapibus mensas onerabat inemptis.<br>Primus vere rosam atque autumno carpere poma,<br>et cum tristis hiems etiamnum frigore saxa<br>rumperet et glacie cursus frenaret aquarum,<br>ille comam mollis iam tondebat hyacinthi<br>aestatem increpitans seram Zephyrosque morantes.<br>Ergo apibus fetis idem atque examine multo<br>primus abundare et spumantia cogere pressis<br>mella favis; illi tiliae atque uberrima pinus,<br>quotque in flore novo pomis se fertilis arbos<br>induerat, totidem autumno matura tenebat.<br>Ille etiam seras in versum distulit ulmos<br>eduramque pirum et spinos iam pruna ferentes<br>iamque ministrantem platanum potantibus umbras.<br>Verum haec ipse equidem spatiis exclusus iniquis<br>praetereo atque aliis post me memoranda relinquo.","st":"4"},{"sp":"N","t":"Nunc age, naturas apibus quas Iuppiter ipse<br>addidit, expediam, pro qua mercede canoros<br>Curetum sonitus crepitantiaque aera secutae<br>Dictaeo caeli regem pavere sub antro.<br>Solae communes natos, consortia tecta<br>urbis habent magnisque agitant sub legibus aevum,<br>et patriam solae et certos novere penates,<br>venturaeque hiemis memores aestate laborem<br>experiuntur et in medium quaesita reponunt.<br>Namque aliae victu invigilant et foedere pacto<br>exercentur agris; pars intra saepta domorum<br>Narcissi lacrimam et lentum de cortice gluten<br>prima favis ponunt fundamina, deinde tenaces<br>suspendunt ceras: aliae spem gentis adultos<br>educunt fetus, aliae purissima mella<br>stipant et liquido distendunt nectare cellas.<br>Sunt quibus ad portas cecidit custodia sorti,<br>inque vicem speculantur aquas et nubila caeli<br>aut onera accipiunt venientum aut agmine facto<br>ignavum fucos pecus a praesepibus arcent.<br>Fervet opus, redolentque thymo fragrantia mella.<br>ac veluti lentis Cyclopes fulmina massis<br>cum properant, alii taurinis follibus auras<br>accipiunt redduntque, alii stridentia tingunt<br>aera lacu; gemit impositis incudibus Aetna;<br>illi inter sese magna vi bracchia tollunt<br>in numerum versantque tenaci forcipe ferrum:<br>non aliter, si parva licet componere magnis,<br>Cecropias innatus apes amor urget habendi,<br>munere quamque suo. Grandaevis oppida curae<br>et munire favos et daedala fingere tecta.<br>At fessae multa referunt se nocte minores,<br>crura thymo plenae; pascuntur et arbuta passim<br>et glaucas salices casiamque crocumque rubentem<br>et pinguem tiliam et ferrugineos hyacinthos.<br>Omnibus una quies operum, labor omnibus unus:<br>mane ruunt portis; nusquam mora; rursus easdem<br>vesper ubi e pastu tandem decedere campis<br>admonuit, tum tecta petunt, tum corpora curant;<br>fit sonitus, mussantque oras et limina circum.<br>Post, ubi iam thalamis se composuere, siletur<br>in noctem fessosque sopor suus occupat artus.<br>Nec vero a stabulis pluvia impendente recedunt<br>longius aut credunt caelo adventantibus Euris,<br>sed circum tutae sub moenibus urbis aquantur,<br>excursusque breves temptant et saepe lapillos,<br>ut cumbae instabiles fluctu iactante saburram,<br>tollunt, his sese per inania nubila librant.<br>Illum adeo placuisse apibus mirabere morem,<br>quod neque concubitu indulgent nec corpora segnes<br>in Venerem solvunt aut fetus nixibus edunt:<br>verum ipsae e foliis natos, e suavibus herbis<br>ore legunt, ipsae regem parvosque Quirites<br>sufficiunt aulasque et cerea regna refigunt.<br>*Saepe etiam duris errando in cotibus alas<br>attrivere ultroque animam sub fasce dedere:<br>tantus amor florum et generandi gloria mellis.<br>Ergo ipsas quamvis angusti terminus aevi<br>excipiat, neque enim plus septima ducitur aestas,<br>at genus immortale manet multosque per annos<br>stat fortuna domus et avi numerantur avorum.<br>Praeterea regem non sic Aegyptus et ingens<br>Lydia nec populi Parthorum aut Medus Hydaspes<br>observant. Rege incolumi mens omnibus una est;<br>amisso rupere fidem constructaque mella<br>diripuere ipsae et crates solvere favorum.<br>Ille operum custos, illum admiruntur et omnes<br>circumstant fremitu denso stipantque frequentes<br>et saepe attollunt umeris et corpora bello<br>obiectant pulchramque petunt per vulnera mortem.","st":"4"},{"sp":"N","t":"His quidam signis atque haec exempla secuti<br>esse apibus partem divinae mentis et haustus<br>aetherios dixere; deum namque ire per omnes<br>terrasque tractusque maris caelumque profundum.<br>Hinc pecudes, armenta, viros, genus omne ferarum,<br>quemque sibi tenues nascentem arcessere vitas;<br>scilicet huc reddi deinde ac resoluta referri<br>omnia nec morti esse locum, sed viva volare<br>sideris in numerum atque alto succedere caelo.","st":"4"},{"sp":"N","t":"Si quando sedem angustam servataque mella<br>thesauris relines, prius haustu sparsus aquarum<br>ora fove fumosque manu praetende sequaces.<br>Bis gravidos cogunt fetus, duo tempora messis,<br>Taygete simul os terris ostendit honestum<br>Pleas et Oceani spretos pede reppulit amnes,<br>aut eadem sidus fugiens ubi Piscis aquosi<br>tristior hibernas caelo descendit in undas.<br>Illis ira modum supra est, laesaeque venenum<br>morsibus inspirant et spicula caeca relinquunt<br>adfixae venis animasque in vulnere ponunt.<br>Sin duram metues hiemem parcesque futuro<br>contunsosque animos et res miserabere fractas,<br>at suffire thymo cerasque recidere inanes<br>quis dubitet? nam saepe favos ignotus adedit<br>stellio et lucifugis congesta cubilia blattis<br>immunisque sedens aliena ad pabula fucus<br>aut asper crabro imparibus se immiscuit armis,<br>aut dirum tiniae genus, aut invisa Minervae<br>laxos in foribus suspendit aranea casses.<br>Quo magis exhaustae fuerint, hoc acrius omnes<br>incumbent generis lapsi sarcire ruinas<br>complebuntque foros et floribus horrea texent.","st":"4"},{"sp":"N","t":"Si vero, quoniam casus apibus quoque nostros<br>vita tulit, tristi languebunt corpora morbo — -<br>quod iam non dubiis poteris cognoscere signis:<br>continuo est aegris alius color, horrida vultum<br>deformat macies, tum corpora luce carentum<br>exportant tectis et tristia funera ducunt;<br>aut illae pedibus conexae ad limina pendent,<br>aut intus clausis cunctantur in aedibus, omnes<br>ignavaeque fame et contracto frigore pigrae.<br>Tum sonus auditur gravior, tractimque susurrant,<br>frigidus ut quondam silvis immurmurat Auster,<br>ut mare sollicitum stridit refluentibus undis,<br>aestuat ut clausis rapidus fornacibus ignis:<br>hic iam galbaneos suadebo incendere odores<br>mellaque harundineis inferre canalibus, ultro<br>hortantem et fessas ad pabula nota vocantem.<br>Proderit et tunsum gallae admiscere saporem<br>Arentesque rosas aut igni pinguia multo<br>defruta vel psithia passos de vite racemos<br>Cecropiumque thymum et grave olentia centaurea.<br>Est etiam flos in pratis, cui nomen amello<br>fecere agricolae, facilis quaerentibus herba;<br>namque uno ingentem tollit de caespite silvam,<br>aureus ipse, sed in foliis, quae plurima circum<br>funduntur, violae sublucet purpura nigrae;<br>[saepe deum nexis ornatae torquibus arae;]<br>asper in ore sapor; tonsis in vallibus illum<br>pastores et curva legunt prope flumina Mellae.<br>Huius odorato radices incoque Baccho<br>pabulaque in foribus plenis adpone canistris.","st":"4"},{"sp":"N","t":"Sed siquem proles subito defecerit omnis,<br>nec genus unde novae stirpis revocetur habebit,<br>tempus et Arcadii memoranda inventa magistri<br>pandere, quoque modo caesis iam saepe iuvencis<br>insincerus apes tulerit cruor. Altius omnem<br>expediam prima repetens ab origine famam.<br>Nam qua Pellaei gens fortunata Canopi<br>accolit effuso stagnantem flumine Nilum<br>et circum pictis vehitur sua rura phaselis,<br>quaque pharetratae vicinia Persidis urget,<br>[et viridem Aegyptum nigra fecundat harena,<br>et diversa ruens septem discurrit in ora<br>usque coloratis amnis devexus ab Indis]<br>omnis in hac certam regio iacit arte salutem.<br>Exiguus primum atque ipsos contractus in usus<br>eligitur locus; hunc angustique imbrice tecti<br>parietibusque premunt artis et quattuor addunt,<br>quattuor a ventis obliqua luce fenestras.<br>Tum vitulus bima curvans iam cornua fronte<br>quaeritur; huic geminae nares et spiritus oris<br>multa reluctanti obstruitur, plagisque perempto<br>tunsa per integram solvuntur viscera pellem.<br>Sic positum in clauso linquunt et ramea costis<br>subiciunt fragmenta, thymum casiasque recentes.<br>Hoc geritur Zephyris primum impellentibus undas,<br>ante novis rubeant quam prata coloribus, ante<br>garrula quam tignis nidum suspendat hirundo.<br>Interea teneris tepefactus in ossibus umor<br>aestuat et visenda modis animalia miris,<br>trunca pedum primo, mox et stridentia pennis,<br>miscentur tenuemque magis magis aera carpunt,<br>donec, ut aestivis effusus nubibus imber,<br>erupere aut ut nervo pulsante sagittae,<br>prima leves ineunt si quando proelia Parthi.","st":"4"},{"sp":"N","t":"Quis deus hanc, Musae, quis nobis extudit artem?<br>Unde nova ingressus hominum experientia cepit?<br>Pastor Aristaeus fugiens Peneia Tempe,<br>amissis, ut fama, apibus morboque fameque,<br>tristis ad extremi sacrum caput adstitit amnis<br>multa querens atque hac adfatus voce parentem:<br>`Mater, Cyrene mater, quae gurgitis huius<br>ima tenes, quid me praeclara stirpe deorum,<br>si modo, quem perhibes, pater est Thymbraeus Apollo,<br>invisum fatis genuisti? aut quo tibi nostri<br>pulsus amor? quid me caelum sperare iubebas?<br>En etiam hunc ipsum vitae mortalis honorem,<br>quem mihi vix frugum et pecudum custodia sollers<br>omnia temptanti extuderat, te matre relinquo.<br>Quin age et ipsa manu felices erue silvas,<br>fer stabulis inimicum ignem atque interfice messes,<br>ure sata et validam in vites molire bipennem,<br>tanta meae si te ceperunt taedia laudis.’<br>At mater sonitum thalamo sub fluminis alti<br>sensit. Eam circum Milesia vellera Nymphae<br>carpebant hyali saturo fucata colore,<br>drymoque Xanthoque Ligeaque Phyllodoceque,<br>caesariem effusae nitidam per candida colla,<br>Nesaee Spioque Thaliaque Cymodoceque,<br>Cydippeque et flava Lycorias, altera virgo,<br>altera tum primos Lucinae experta labores,<br>Clioque et Beroe soror, Oceanitides ambae,<br>ambae auro, pictis incinctae pellibus ambae,<br>atque Ephyre atque Opis et Asia Deiopea<br>et tandem positis velox Arethusa sagittis.<br>Inter quas curam Clymene narrabat inanem<br>Vulcani Martisque dolos et dulcia furta,<br>aque Chao densos divum numerabat amores<br>carmine quo captae dum fusis mollia pensa<br>devolvunt, iterum maternas impulit aures<br>luctus Aristaei, vitreisque sedilibus omnes<br>obstipuere; sed ante alias Arethusa sorores<br>prospiciens summa flavum caput extulit unda<br>et procul: `O gemitu non frustra exterrita tanto,<br>Cyrene soror, ipse tibi, tua maxima cura,<br>tristis Aristaeus Penei genitoris ad undam<br>stat lacrimans et te crudelem nomine dicit.’<br>Huic percussa nova mentem formidine mater,<br>`duc, age, duc ad nos; fas illi limina divum<br>tangere,’ ait. Simul alta iubet discedere late<br>flumina, qua iuvenis gressus inferret. At illum<br>curvata in montis faciem circumstetit unda<br>accepitque sinu vasto misitque sub amnem.<br>Iamque domum mirans genetricis et umida regna<br>speluncisque lacus clausos lucosque sonantes<br>ibat et ingenti motu stupefactus aquarum<br>omnia sub magna labentia flumina terra<br>spectabat diversa locis, Phasimque Lycumque<br>et caput, unde altus primum se erumpit Enipeus<br>unde pater Tiberinus et unde Aniena fluenta<br>saxosusque sonans Hypanis Mysusque Caicus,<br>et gemina auratus taurino cornua vultu<br>Eridanus, quo non alius per pinguia culta<br>in mare purpureum violentior effluit amnis.<br>Postquam est in thalami pendentia pumice tecta<br>perventum et nati fletus cognovit inanes<br>Cyrene, manibus liquidos dant ordine fontes<br>germanae tonsisque ferunt mantelia villis;<br>pars epulis onerant mensas et plena reponunt<br>pocula, Panchaeis adolescunt ignibus arae;<br>et mater, `Cape Maeonii carchesia Bacchi:<br>Oceano libemus,’ ait. Simul ipsa precatur<br>Oceanumque patrem rerum Nymphasque sorores<br>centum quae silvas, centum quae flumina servant.<br>Ter liquido ardentem perfundit nectare Vestam,<br>ter flamma ad summum tecti subiecta reluxit.<br>Omine quo firmans animum sic incipit ipsa:","st":"4"},{"sp":"N","t":"`Est in Carphatio Neptuni gurgite vates<br>caeruleus Proteus, magnum qui piscibus aequor<br>et iuncto bipedum curru metitur equorum.<br>Hic nunc Emathiae portus patriamque revisit<br>Pallenen, hunc et Nymphae veneramur et ipse<br>grandaevus Nereus; novit namque omnia vates,<br>quae sint, quae fuerint, quae mox ventura trahantur;<br>quippe ita Neptuno visum est, immania cuius<br>armenta et turpes pascit sub gurgite phocas.<br>Hic tibi, nate, prius vinclis capiendus, ut omnem<br>expediat morbi causam eventusque secundet.<br>Nam sine vi non ulla dabit praecepta, neque illum<br>orando flectes; vim duram et vincula capto<br>tende; doli circum haec demum frangentur inanes.<br>Ipsa ego, te, medios cum sol accenderit aestus,<br>cum sitiunt herbae et pecori iam gratior umbra est,<br>in secreta senis ducam, quo fessus ab undis<br>se recipit, facile ut somno adgrediare iacentem.<br>Verum ubi correptum manibus vinclisque tenebis,<br>tum variae eludent species atque ora ferarum<br>Fiet enim subito sus horridus atraque tigris<br>squamosusque draco et fulva cervice leaena,<br>aut acrem flammae sonitum dabit atque ita vinclis<br>excidet, aut in aquas tenues dilapsus abibit.<br>Sed quanto ille magis formas se vertet in omnes,<br>tanto, nate, magis contende tenacia vincla,<br>donec talis erit mutato corpore, qualem<br>videris, incepto tegeret cum lumina somno.","st":"4"},{"sp":"N","t":"Haec ait et liquidum ambrosiae defundit odorem,<br>quo totum nati corpus perduxit; at illi<br>dulcis compositis spiravit crinibus aura<br>atque habilis membris venit vigor. Est specus ingens<br>exesi latere in montis, quo plurima vento<br>cogitur inque sinus scindit sese unda reductos,<br>deprensis olim statio tutissima nautis;<br>intus se vasti Proteus tegit obice saxi.<br>Hic iuvenem in latebris aversum a lumine Nympha<br>collocat; ipsa procul nebulis obscura resistit.<br>Iam rapidus torrens sitientes Sirius Indos<br>ardebat, caelo et medium sol igneus orbem<br>hauserat; arebant herbae et cava flumina siccis<br>faucibus ad limum radii tepefacta coquebant:<br>cum Proteus consueta petens e fluctibus antra<br>ibat; eum vasti circum gens umida ponti<br>exsultans rorem late dispergit amarum.<br>Sternunt se somno diversae in litore phocae.<br>Ipse, velut stabuli custos in montibus olim,<br>vesper ubi e pastu vitulos ad tecta reducit,<br>auditisque lupos acuunt balatibus agni,<br>considit scopulo medius numerumque recenset.<br>Cuius Aristaeo quoniam est oblata facultas,<br>vix defessa senem passus componere membra<br>cum clamore ruit magno manicisque iacentem<br>occupat. Ille suae contra non immemor artis<br>omnia transformat sese in miracula rerum,<br>ignemque horribilemque feram fluviumque liquentem.<br>Verum ubi nulla fugam reperit fallacia, victus<br>in sese redit atque hominis tandem ore locutus:<br>`Nam quis te, iuvenum confidentissime, nostras<br>iussit adire domos? Quidve hinc petis?’ inquit. At ille:<br>`Scis, Proteu, scis ipse; neque est te fallere quicquam<br>sed tu desine velle. Deum praecepta secuti<br>venimus hinc lapsis quaesitum oracula rebus.<br>Tantum effatus. Ad haec vates vi denique multa<br>ardentes oculos intorsit lumine glauco<br>et graviter frendens sic fatis ora resolvit.","st":"4"},{"sp":"N","t":"Non te nullius exercent numinis irae;<br>magna luis commissa: tibi has miserabilis Orpheus<br>haudquaquam ob meritum poenas, ni fata resistant,<br>suscitat et rapta graviter pro coniuge saevit.<br>Illa quidem, dum te fugeret per flumina praeceps,<br>immanem ante pedes hydrum moritura puella<br>servantem ripas alta non vidit in herba.<br>At chorus aequalis Dryadum clamore supremos<br>implerunt montes; flerunt Rhodopeiae arces<br>altaque Pangaea et Rhesi mavortia tellus<br>atque Getae atque Hebrus et Actias Orithyia.<br>Ipse cava solans aegrum testudine amorem<br>te, dulcis coniunx, te solo in litore secum,<br>te veniente die, te decedente canebat.<br>Taenarias etiam fauces, alta ostia Ditis,<br>et caligantem nigra formidine lucum<br>ingressus manesque adiit regemque tremendum<br>nesciaque humanis precibus mansuescere corda.<br>At cantu commotae Erebi de sedibus imis<br>umbrae ibant tenues simulacraque luce carentum,<br>quam multa in foliis avium se milia condunt<br>vesper ubi aut hibernus agit de montibus imber,<br>matres atque viri defunctaque corpora vita<br>magnanimum heroum, pueri innuptaeque puellae,<br>impositique rogis iuvenes ante ora parentum,<br>quos circum limus niger et deformis harundo<br>Cocyti tardaque palus inamabilis unda<br>alligat et noviens Styx interfusa coercet.<br>Quin ipsae stupuere domus atque intima Leti<br>tartara caeruleosque implexae crinibus angues<br>Eumenides, tenuitque inhians tria Cerberus ora<br>atque Ixionii vento rota constitit orbis.<br>Iamque pedem referens casus evaserat omnes;<br>redditaque Eurydice superas veniebat ad auras,<br>pone sequens, namque hanc dederat Proserpina legem,<br>cum subita incautum dementia cepit amantem,<br>ignoscenda quidem, scirent si ignoscere manes.<br>Restitit Eurydicenque suam iam luce sub ipsa<br>immemor heu! victusque animi respexit. Ibi omnis<br>effusus labor atque immitis rupta tyranni<br>foedera, terque fragor stagnis auditus Avernis.<br>Illa, Quis et me, inquit, miseram et te perdidit, Orpheu,<br>quis tantus furor? En iterum crudelia retro<br>Fata vocant, conditque natantia lumina somnus.<br>Iamque vale: feror ingenti circumdata nocte<br>invalidasque tibi tendens, heu non tua, palmas!<br>dixit et ex oculis subito, ceu fumus in auras<br>commixtus tenues, fugit diversa, neque illum,<br>prensantem nequiquam umbras et multa volentem<br>dicere, praeterea vidit, nec portitor Orci<br>amplius obiectam passus transire paludem.<br>Quid faceret? Quo se rapta bis coniuge ferret?<br>Quo fletu Manis, quae numina voce moveret?<br>Illa quidem Stygia nabat iam frigida cumba.<br>Septem illum totos perhibent ex ordine menses<br>rupe sub aeria deserti ad Strymonis undam<br>flesse sibi et gelidis haec evolvisse sub antris<br>mulcentem tigres et agentem carmine quercus;<br>qualis populea maerens philomela sub umbra<br>amissos queritur fetus, quos durus arator<br>observans nido implumes detraxit; at illa<br>flet noctem ramoque sedens miserabile carmen<br>integrat et maestis late loca questibus implet.<br>Nulla Venus, non ulli animum flexere hymenaei.<br>Solus Hyperboreas glacies Tanaimque nivalem<br>arvaque Rhipaeis numquam viduata pruinis<br>lustrabat raptam Eurydicen atque inrita Ditis<br>dona querens; spretae Ciconum quo munere matres<br>inter sacra deum nocturnique orgia Bacchi<br>discerptum latos iuvenem sparsere per agros.<br>Tum quoque marmorea caput a cervice revulsum<br>gurgite cum medio portans Oeagrius Hebrus<br>volveret, Eurydicen vox ipsa et frigida lingua<br>ah miseram Eurydicen! anima fugiente vocabat:<br>Eurydicen toto referebant flumine ripae.","st":"4"},{"sp":"N","t":"Haec Proteus, et se iactu dedit aequor in altum,<br>quaque dedit, spumantem undam sub vertice torsit.<br>At non Cyrene; namque ultro adfata timentem:","st":"4"},{"sp":"N","t":"`Nate, licet tristes animo deponere curas.<br>Haec omnis morbi causa; hinc miserabile Nymphae,<br>cum quibus illa choros lucis agitabat in altis,<br>exitium misere apibus. Tu munera supplex<br>tende petens pacem et faciles venerare Napaeas;<br>namque dabunt veniam votis irasque remittent.<br>Sed modus orandi qui sit, prius ordine dicam.<br>Quattuor eximios praestanti corpore tauros,<br>qui tibi nunc viridis depascunt summa Lycaei,<br>delige et intacta totidem cervice iuvencas.<br>Quattuor his aras alta ad delubra dearum<br>constitue et sacrum iugulis demitte cruorem,<br>corporaque ipsa boum frondoso desere luco.<br>Post, ubi nona suos Aurora ostenderit ortus,<br>inferias Orphei Lethaea papavera mittes<br>et nigram mactabis ovem lucumque revises:<br>placatam Eurydicen vitula venerabere caesa.","st":"4"},{"sp":"N","t":"Haud mora; continuo matris praecepta facessit;<br>ad delubra venit, monstratas excitat aras,<br>quattuor eximios praestanti corpore tauros<br>ducit et intacta totidem cervice iuvencas.<br>Post, ubi nona suos Aurora induxerat ortus,<br>inferias Orphei mittit lucumque revisit.<br>Hic vero subitum ac dictu mirabile monstrum<br>adspiciunt, liquefacta boum per viscera toto<br>stridere apes utero et ruptis effervere costis,<br>immensasque trahi nubes, iamque arbore summa<br>confluere et lentis uvam demittere ramis.","st":"4"},{"sp":"N","t":"Haec super arvorum cultu pecorumque canebam<br>et super arboribus, Caesar dum magnus ad altum<br>fulminat Euphraten bello victorque volentes<br>per populos dat iura viamque adfectat Olympo.<br>Illo Vergilium me tempore dulcis alebat<br>Parthenope studiis florentem ignobilis oti,<br>carmina qui lusi pastorum audaxque iuventa,<br>Tityre, te patulae cecini sub tegmine fagi.","st":"4"}]);})();
